window.SOCIAL_DATA=window.SOCIAL_DATA||[];window.SOCIAL_DATA.push({"levels": {"必考": 17, "常考": 6}, "mapname": {"map-nsong": "北宋與周邊民族形勢圖（含燕雲十六州）", "map-ssong": "南宋與周邊民族形勢圖", "map-mongol": "蒙古西征路線及其疆域圖", "qingming": "《清明上河圖》（插畫）", "chao-zhongtong": "元代紙幣「中統元寶交鈔」", "chao-zhiyuan": "元代紙幣「至元通行寶鈔」（對照）"}, "id": "hist-3", "subject": "歷史", "chapter": "第三章", "title": "宋元多民族並立的時期", "total": 232, "concepts": [{"id": "c4", "name": "金國崛起、靖康之禍與南宋偏安", "n": 33, "level": "必考", "card": {"說明": "北宋末年，東北長白山一帶的女真族首領完顏阿骨打起兵反遼建金。北宋為收復燕雲十六州採取「聯金滅遼」政策，金滅遼後察覺北宋軍力空虛遂大舉南侵。西元1127年金兵攻陷汴京，俘虜宋徽宗、宋欽宗北去，史稱「靖康之禍」，北宋滅亡。宋高宗趙構南渡建立南宋，定都臨安。", "關鍵名詞": "<b>靖康之禍</b>——西元1127年女真金國攻破汴京並擄走宋徽宗、宋欽宗二帝與宗室，導致北宋滅亡的重大事變。", "因果／影響": "中原全境淪入金國統治，宋朝政權偏安江淮以南；岳飛等將領積極抗金，兩國後續劃淮河一線形成南北長期對峙。", "出處": "自修第21頁／講義第32頁、速讀秘笈第21頁", "標示": "講義「重點分析」、段考常考題"}, "imgs": ["map-ssong"], "clusters": [{"t": "靖康之禍是北宋變南宋的關鍵", "n": 6, "ids": ["h3-24", "h3-44", "h3-106", "h3-140", "h3-212", "h3-224"]}, {"t": "岳飛抗金：「胡虜」指女真", "n": 7, "ids": ["h3-27", "h3-75", "h3-91", "h3-152", "h3-174", "h3-198", "h3-203"]}, {"t": "北宋亡於金、南宋亡於蒙古", "n": 5, "ids": ["h3-124", "h3-163", "h3-211", "h3-213", "h3-226"]}, {"t": "南宋都臨安、偏安江南", "n": 5, "ids": ["h3-150", "h3-151", "h3-189", "h3-232", "h3-77"]}, {"t": "「靖康恥」的意思", "n": 2, "ids": ["h3-59", "h3-171"]}, {"t": "聯金滅遼（海上之盟）", "n": 3, "ids": ["h3-30", "h3-138", "h3-170"]}, {"t": "東亞政權消長", "n": 6, "ids": ["h3-58", "h3-73", "h3-109", "h3-40", "h3-114", "h3-113"]}]}, {"id": "c8", "name": "宋代都市商業革命：坊市制度瓦解與夜市興盛", "n": 30, "level": "必考", "card": {"說明": "唐代都市實施嚴密的「坊市制度」，住宅區（坊）與商業區（市）嚴格分開且設有夜禁。宋代徹底打破空間隔閡與營業時間限制，商家可在城市各處臨街開店，夜市通宵達旦，形成開放熱鬧的繁華市街。北宋張擇端的《清明上河圖》具體呈現了汴京繁盛市況。", "關鍵名詞": "<b>坊市制度瓦解</b>——宋代打破唐代居住區與商業區隔離、日落閉市的傳統制度，形成臨街設店、日夜皆可營業的開放商業型態。", "因果／影響": "催生熱鬧的庶民生活與娛樂文化（如瓦子勾欄娛樂表演、話本說書與雜劇），促進城市市民階級崛起。", "出處": "自修第22頁／講義第34～35頁、速讀秘笈第21頁", "標示": "講義「延伸學習」、自修「會考模擬題」必考"}, "imgs": ["qingming"], "clusters": [{"t": "住商混合 → 坊市制度廢除", "n": 7, "ids": ["h3-26", "h3-55", "h3-63", "h3-69", "h3-115", "h3-182", "h3-221"]}, {"t": "夜市從宋代開始", "n": 4, "ids": ["h3-47", "h3-60", "h3-82", "h3-190"]}, {"t": "《清明上河圖》＝北宋汴京庶民生活", "n": 11, "ids": ["h3-21", "h3-35", "h3-57", "h3-70", "h3-93", "h3-107", "h3-144", "h3-156", "h3-188", "h3-200", "h3-218"]}, {"t": "宋代科技發達、商業興盛", "n": 2, "ids": ["h3-61", "h3-207"]}, {"t": "判斷宋代生活（排除其他朝代）", "n": 5, "ids": ["h3-6", "h3-76", "h3-177", "h3-215", "h3-229"]}]}, {"id": "c6", "name": "元朝差別待遇的種族政策", "n": 28, "level": "必考", "card": {"說明": "元朝統治者為維持少數蒙古貴族的特權優勢與統治安全，按照征服地區先後將境內人民分為四個階級：蒙古人、色目人、漢人與南人，在法律、任官與科舉上實施嚴格差別待遇。", "關鍵名詞": "<b>色目人</b>——蒙古西征降附的西域以西各民族（如回回、波斯、阿拉伯等），在元朝地位僅次於蒙古人，受重用主持中央與地方財政賦稅。", "因果／影響": "階級壓迫激化了漢人與南人的強烈民族反感，成為元朝末年民變四起、統治迅速瓦解的重要內部主因。", "出處": "自修第22頁／講義第33頁、速讀秘笈第21頁", "標示": "講義「重點分析」、會考高頻考點"}, "imgs": [], "clusters": [{"t": "色目人：西域人、擅理財、馬可波羅", "n": 8, "ids": ["h3-28", "h3-54", "h3-97", "h3-129", "h3-136", "h3-178", "h3-193", "h3-205"]}, {"t": "南人：原南宋地區、地位最低", "n": 4, "ids": ["h3-66", "h3-105", "h3-125", "h3-214"]}, {"t": "科舉考試不公平", "n": 5, "ids": ["h3-38", "h3-110", "h3-119", "h3-179", "h3-219"]}, {"t": "種族政策是元朝衰亡原因", "n": 3, "ids": ["h3-45", "h3-90", "h3-117"]}, {"t": "四等人辨識", "n": 7, "ids": ["h3-3", "h3-127", "h3-195", "h3-206", "h3-222", "h3-23", "h3-67"]}, {"t": "看時間軸找出元朝", "n": 1, "ids": ["h3-164"]}]}, {"id": "c5", "name": "蒙古帝國擴張、三次西征與元朝統一", "n": 27, "level": "必考", "card": {"說明": "13世紀初，鐵木真統一蒙古草原各部落被尊為「成吉思汗」，隨後展開三次橫跨歐亞的西征，攻滅西夏、花剌子模與巴格達等地，奠定四大汗國版圖。忽必烈即位後改國號為「大元」，定都大都（今北京），於1279年攻滅南宋統一全中國。", "關鍵名詞": "<b>四大汗國</b>——蒙古發動三次西征後，由蒙古宗室統治的四個橫跨歐亞的大汗國（欽察、察合台、窩闊台、伊兒汗國）。", "因果／影響": "結束了自唐末五代以來數百年的多民族政權分裂割據，建立中國歷史上首個完全統治整個中國本土的草原少數民族大一統帝國，同時貫通歐亞陸海交通。", "出處": "自修第21～22頁／講義第32頁、速讀秘笈第21頁", "標示": "講義「會考精熟題」、自修「重點整理」"}, "imgs": ["map-mongol"], "clusters": [{"t": "三次西征、四大汗國", "n": 9, "ids": ["h3-5", "h3-149", "h3-135", "h3-185", "h3-204", "h3-230", "h3-231", "h3-41", "h3-18"]}, {"t": "鐵木真 vs 忽必烈", "n": 7, "ids": ["h3-25", "h3-79", "h3-108", "h3-131", "h3-157", "h3-184", "h3-220"]}, {"t": "歐洲人口中的「黃禍」", "n": 2, "ids": ["h3-130", "h3-197"]}, {"t": "元滅南宋、統一中國", "n": 5, "ids": ["h3-4", "h3-71", "h3-78", "h3-225", "h3-172"]}, {"t": "元大都（汗八里）", "n": 2, "ids": ["h3-32", "h3-33"]}, {"t": "蒙古打敗金國", "n": 1, "ids": ["h3-126"]}]}, {"id": "c10", "name": "宋元對外貿易：海路市舶司與陸路驛站網絡", "n": 21, "level": "必考", "card": {"說明": "宋代因北方陸路交通受外族割據阻隔，對外貿易重心轉向海上絲路，官府於泉州、廣州等重要港口設置「市舶司」管理外商外舶並徵收關稅。元朝統一後海陸暢通，陸路廣泛建立「驛站」系統，頒發牌符提供信差、商旅與官員換馬歇宿，建構出完整的歐亞路網。", "關鍵名詞": "• <b>市舶司</b>：唐設宋元極盛的海洋商貿主管機關，職司外商管理、商船進出檢查與關稅徵收（地位相當於近代海關）。<br>• <b>驛站</b>：元朝為維繫橫跨歐亞遼闊疆土而鋪設的交通交通管理系統，提供差役、商人換馬食宿。", "因果／影響": "泉州發展為當時世界公認的東方第一大商港；陸海交通的貫通促成東西方物質、技術與文化的大規模直接交流。", "出處": "自修第22頁／講義第34頁、速讀秘笈第21頁", "標示": "講義「重點整理」、會考歷屆考題"}, "imgs": [], "clusters": [{"t": "市舶司＝今日海關", "n": 6, "ids": ["h3-7", "h3-36", "h3-48", "h3-81", "h3-155", "h3-209"]}, {"t": "驛站是元代（蒙古）設立", "n": 6, "ids": ["h3-10", "h3-49", "h3-80", "h3-89", "h3-98", "h3-161"]}, {"t": "宋代港口：泉州、廣州", "n": 4, "ids": ["h3-19", "h3-50", "h3-102", "h3-64"]}, {"t": "「北宋不可能」看到驛站", "n": 3, "ids": ["h3-29", "h3-169", "h3-42"]}, {"t": "元代海陸貿易", "n": 2, "ids": ["h3-22", "h3-199"]}]}, {"id": "c3", "name": "澶淵之盟與宋遼對等外交", "n": 20, "level": "必考", "card": {"說明": "宋真宗在位期間，遼軍大舉南侵逼近宋境，宰相寇準力勸真宗親征前線澶州督戰，宋軍士氣大振。雙方僵持下於前線達成和平協議，簽署「澶淵之盟」，宋真宗與遼聖宗約定以兄弟相稱。", "關鍵名詞": "<b>歲幣</b>——澶淵之盟簽訂後，北宋每年給予遼國固定數額的銀兩與絹帛。", "因果／影響": "開啟中原王朝與周邊草原游牧政權建立「對等外交」的先例；儘管歲幣造成財政開支，但維繫了宋遼雙方一百二十餘年的長久和平，邊境互市繁榮且軍費支出大幅降低。", "出處": "自修第21頁／講義第31頁、速讀秘笈第21頁", "標示": "講義「會考精熟題」、自修「必考重點」"}, "imgs": ["map-nsong"], "clusters": [{"t": "對象是遼、兄弟相稱、百年和平", "n": 9, "ids": ["h3-2", "h3-46", "h3-72", "h3-92", "h3-137", "h3-141", "h3-159", "h3-176", "h3-228"]}, {"t": "簽約的是宋真宗（寇準建議親征）", "n": 4, "ids": ["h3-74", "h3-142", "h3-154", "h3-217"]}, {"t": "每年給歲幣", "n": 3, "ids": ["h3-34", "h3-112", "h3-202"]}, {"t": "看圖判斷北宋國際關係", "n": 4, "ids": ["h3-39", "h3-145", "h3-160", "h3-208"]}]}, {"id": "c11", "name": "理學的形成與朱熹《四書集注》", "n": 18, "level": "必考", "card": {"說明": "宋代在崇文風氣下，儒家學者融合佛教哲理與道家宇宙觀，重新詮釋儒學義理，形成新儒學「理學」。南宋朱熹集理學大成，為《大學》、《中庸》、《論語》、《孟子》作注編撰《四書集注》。", "關鍵名詞": "<b>四書集注</b>——南宋朱熹編撰之理學核心著作，元代復辦科舉後定為官方科舉考試的命題教科書範本。", "因果／影響": "奠定元、明、清三朝科舉與官方哲學的指導地位，對東亞文化圈（朝鮮半島、日本）產生長遠思想影響。", "出處": "自修第22頁／講義第35頁、速讀秘笈第21頁", "標示": "講義「會考精熟題」、自修「基礎實力題」"}, "imgs": [], "clusters": [{"t": "理學融合佛學", "n": 5, "ids": ["h3-51", "h3-85", "h3-128", "h3-166", "h3-94"]}, {"t": "朱熹集理學大成", "n": 3, "ids": ["h3-12", "h3-120", "h3-165"]}, {"t": "《四書集注》元代成為科舉定本", "n": 7, "ids": ["h3-14", "h3-16", "h3-83", "h3-153", "h3-168", "h3-201", "h3-216"]}, {"t": "理學傳到朝鮮、日本", "n": 3, "ids": ["h3-84", "h3-96", "h3-147"]}]}, {"id": "c12", "name": "宋代三大發明的演進與西傳", "n": 17, "level": "必考", "card": {"說明": "宋元時期中國科學技術高度成熟，火藥、活字印刷術與指南針在生活、軍事與交通上普遍應用並向外傳播。<br>• 火藥：宋代廣泛製造爆破性武器投入防禦作戰，後經蒙古西征傳播至西亞與歐洲，革新世界軍事作戰模式。<br>• 活字印刷術：北宋畢昇發明膠泥活字版，突破雕版印刷無法拆組重複使用的瓶頸，提升書籍複製效率。<br>• 指南針：宋代開始應用於遠洋航海定位，經阿拉伯人傳入歐洲，成為歐洲大航海時代的關鍵導航工具。", "關鍵名詞": "<b>活字印刷術</b>——北宋畢昇創製使用單個膠泥活字排版印書之技術，可拆卸拼版重複利用。", "因果／影響": "三大技術經由阿拉伯人與蒙古西征外傳歐洲，推動歐洲封建制度瓦解、文藝復興文化普及與地理大發現的展開。", "出處": "自修第23頁／講義第36頁、速讀秘笈第21頁", "標示": "自修「重點精華」、評量單「必考題」"}, "imgs": [], "clusters": [{"t": "指南針經阿拉伯人傳入歐洲", "n": 6, "ids": ["h3-56", "h3-88", "h3-100", "h3-132", "h3-167", "h3-227"]}, {"t": "火藥經蒙古西征西傳", "n": 5, "ids": ["h3-13", "h3-68", "h3-99", "h3-183", "h3-173"]}, {"t": "畢昇活字印刷", "n": 3, "ids": ["h3-15", "h3-52", "h3-116"]}, {"t": "三大發明辨識（造紙術不算）", "n": 3, "ids": ["h3-134", "h3-146", "h3-187"]}]}, {"id": "c13", "name": "伊斯蘭文化的輸入與交流（回回與回回藥方）", "n": 12, "level": "常考", "card": {"說明": "宋代海運發達吸引大批阿拉伯、波斯商人定居泉州、廣州等地，興建清真寺。元朝西征將西域穆斯林大批納入版圖，色目人中的回回人遍布全國，將伊斯蘭世界的天文曆法、數學與醫學系統引進中國，《回回藥方》即為中阿醫藥交融之代表典籍。", "關鍵名詞": "<b>《回回藥方》</b>——元代融合阿拉伯醫學技術與特色用藥（如芳香劑、糖漿劑型）的官方醫藥文獻。", "因果／影響": "豐富中國傳統科技與醫藥內涵，促成伊斯蘭文化在中國本土的扎根與融合。", "出處": "自修第23頁／講義第36頁、隨堂評量單第6回第6頁", "標示": "講義「延伸學習」、自修「精熟思考題」<br>---"}, "imgs": [], "clusters": [{"t": "伊斯蘭教隨商人傳入", "n": 3, "ids": ["h3-53", "h3-86", "h3-210"]}, {"t": "天文曆法、醫學的影響", "n": 4, "ids": ["h3-11", "h3-31", "h3-87", "h3-196"]}, {"t": "泉州清真寺", "n": 3, "ids": ["h3-123", "h3-158", "h3-186"]}, {"t": "穆斯林屬色目人", "n": 1, "ids": ["h3-133"]}]}, {"id": "c7", "name": "宋代農業革命（占城稻引進）", "n": 9, "level": "常考", "card": {"說明": "北宋真宗時期自中南半島引進占城稻。占城稻具備早熟（生長週期約60至100天）、耐旱耐貧瘠與產量穩定的優勢，可在水利條件較差的丘陵高地與梯田大規模推廣。", "關鍵名詞": "<b>占城稻</b>——引進自占城（今越南南部）的耐旱早熟高產水稻品種。", "因果／影響": "突破水稻傳統種植地理限制，擴大耕作面積並大幅提高糧食總產量，奠定宋代人口突破一億大關與南方經濟重心的基礎。", "出處": "自修第22頁／講義第34～35頁", "標示": "講義「重點分析」、會考評量必考"}, "imgs": [], "clusters": [{"t": "早熟稻來自占城（越南）", "n": 6, "ids": ["h3-8", "h3-43", "h3-62", "h3-95", "h3-121", "h3-192"]}, {"t": "宋代引進（番薯是明代）", "n": 3, "ids": ["h3-111", "h3-162", "h3-223"]}]}, {"id": "c1", "name": "遼的興起與燕雲十六州", "n": 6, "level": "常考", "card": {"說明": "唐朝滅亡後的五代十國動盪之際，北方契丹族迅速壯大並建立大遼政權。後晉石敬瑭為求得契丹軍事支持自立，割讓軍事重鎮燕雲十六州，使遼國國力與防禦縱深大幅擴展。", "關鍵名詞": "<b>燕雲十六州</b>——地處今河北、山西一帶的軍事險隘，為傳統漢人農業民族防禦北方遊牧民族南下的天然長城屏障。", "因果／影響": "燕雲十六州的割讓使中原政權失去北方地勢掩護與長城國防防線，導致後續建立的北宋長期處於防禦被動與外患威脅之下。", "出處": "自修（試題寶典）第21頁／講義第31頁、隨堂評量單第5回第5頁", "標示": "講義「重點分析」、自修「重點精華」、評量單「必考填空題」"}, "imgs": ["map-nsong"], "clusters": [{"t": "燕雲十六州被契丹取得", "n": 4, "ids": ["h3-101", "h3-122", "h3-175", "h3-191"]}, {"t": "遼的勢力", "n": 2, "ids": ["h3-20", "h3-143"]}]}, {"id": "c2", "name": "北宋文人政治（重文輕武與強幹弱枝）", "n": 4, "level": "一般", "card": {"說明": "五代末期後周禁軍將領趙匡胤發動陳橋兵變稱帝，建立宋朝。宋太祖深知唐末五代以來節度使割據與武人奪權的亂象，確立了「重文輕武」與「強幹弱枝」的基本國策，收歸地方精兵、財政與司法於中央，並拔擢文臣掌控軍政大權。", "關鍵名詞": "<b>文人政治</b>——宋朝推行尊崇文官、抑制武將權力，改由文人統帥並指揮國防軍隊的國家治理體制。", "因果／影響": "徹底杜絕了唐末五代以來藩鎮割據、武將篡位的流弊，確保政治體系長治久安；但同時削弱了宋朝對外作戰能力，形成長期的國防積弱。", "出處": "自修第21頁／講義第31頁、隨堂評量單第5回第5頁", "標示": "講義「重點分析」、自修「必考概念」"}, "imgs": [], "clusters": [{"t": "重文輕武 → 國防積弱", "n": 2, "ids": ["h3-104", "h3-180"]}, {"t": "趙匡胤建立北宋", "n": 2, "ids": ["h3-1", "h3-65"]}]}, {"id": "c14", "name": "宋元民族政權綜合辨識", "n": 4, "level": "一般", "card": {}, "imgs": [], "clusters": [{"t": "辨識宋代的外患", "n": 3, "ids": ["h3-103", "h3-118", "h3-139"]}, {"t": "民族與政權配對", "n": 1, "ids": ["h3-194"]}]}, {"id": "c9", "name": "貨幣體系的革新（交子與寶鈔）", "n": 3, "level": "一般", "card": {"說明": "宋代商業貿易空前繁榮，但金屬銅鐵錢過於沉重、長途運送極為困難。北宋四川商人率先發明便於攜帶與結算的紙幣「交子」；元朝更進一步將紙幣確立為法定主幣，設立鈔券提舉司印製「寶鈔」通行全國。", "關鍵名詞": "<b>交子</b>——北宋四川商人為解決鐵錢笨重攜帶問題而發行，為世界歷史上最早的紙幣。", "因果／影響": "極大提升商品交易與跨區域結算效率；但元代後期朝廷無節制濫印紙幣，引發惡性通貨膨脹與經濟崩潰。", "出處": "自修第22頁／講義第34頁、隨堂評量單第6回第6頁", "標示": "講義「重點整理」、自修「精熟思考題」"}, "imgs": ["chao-zhongtong", "chao-zhiyuan"], "clusters": [{"t": "紙幣：北宋交子、元代寶鈔", "n": 3, "ids": ["h3-9", "h3-17", "h3-37"]}]}], "questions": [{"id": "h3-1", "no": 1, "c": "c2", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋代的開國君主本來是五代後周的將領，本已掌握朝廷的政治大權，但在某次戰役中，發生政變而稱帝。上述君主是下列何人？", "o": ["岳飛", "朱熹", "鐵木真", "趙匡胤"], "a": 3, "e": "趙匡胤原為後周禁軍將領，發動陳橋兵變稱帝，建立宋朝。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-2", "no": 2, "c": "c3", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋真宗時北方外患入侵，後來仰賴簽訂盟約，給予歲幣，與其維持了一百多年的和平。上述北方外患應為下列何者？", "o": ["西夏", "遼", "金", "元"], "a": 1, "e": "宋真宗時與遼簽訂澶淵之盟，每年給遼歲幣，雙方維持一百多年和平。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-3", "no": 3, "c": "c6", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "元帝國實施差別待遇的種族政策，下列何者並非四大分類其中之一？", "o": ["蒙古人", "色目人", "女真人", "漢人"], "a": 2, "e": "四等人是蒙古人、色目人、漢人、南人。女真人被歸入「漢人」，不是獨立的一類。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-4", "no": 4, "c": "c5", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "南宋立國之後，面對外患的強大挑戰，始終能夠保持偏安的局面，直到哪一個民族興起，南宋才被此民族所滅？", "o": ["契丹", "女真", "蒙古", "匈奴"], "a": 2, "e": "南宋偏安一百多年，最後在 1279 年被蒙古（元）所滅。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-5", "no": 5, "c": "c5", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "哪一個民族曾經發動三次西征，建立橫跨歐、亞的大帝國？", "o": ["契丹", "女真", "西夏", "蒙古"], "a": 3, "e": "蒙古在成吉思汗與繼位者時發動三次西征，建立橫跨歐亞的大帝國與四大汗國。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-6", "no": 6, "c": "c8", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋元時期經濟貿易興盛，庶民生活更加多彩多姿，下列何者並非當時的發展？", "o": ["逛夜市攤位", "嚴守坊市制度", "使用紙幣購物", "常見外國商人"], "a": 1, "e": "宋代坊市制度瓦解，商店可以隨處開設、夜市興盛；「嚴守坊市制度」是唐代的情形。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-7", "no": 7, "c": "c10", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋元時期，中國對外貿易十分發達，當時設置某機關負責管理，功能如同今日的海關，此機關應為下列何者？", "o": ["市舶司", "洋行", "驛站", "清真寺"], "a": 0, "e": "市舶司管理外國商船、檢查貨物、徵收關稅，功能像今天的海關。驛站是陸上交通設施。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-8", "no": 8, "c": "c7", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋代時自何地引進早熟稻，配合耕作技術的進步，使稻米的產量大增？", "o": ["日本", "越南", "朝鮮", "蒙古"], "a": 1, "e": "早熟稻引自占城（今越南），所以又叫占城稻。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-9", "no": 9, "c": "c9", "src": "自修第 23 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋元時期，因應商業發達的需要，逐漸廣泛使用何種貨幣作為交易媒介？", "o": ["貝殼", "銅錢", "紙幣", "白銀"], "a": 2, "e": "宋代商業發達，銅鐵錢笨重，於是出現紙幣（北宋交子）；元代紙幣（寶鈔）更通行全國。", "rep": false, "img": "", "fh": "", "maps": ["chao-zhongtong"], "chk": ""}, {"id": "h3-10", "no": 10, "c": "c10", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "某個朝代曾在各地廣設驛站，供人歇息，進而促進歐亞等地的貿易與貨物的流通。上述提到的朝代應為下列何者？", "o": ["唐代", "北宋", "南宋", "元代"], "a": 3, "e": "元代（蒙古）廣設驛站，連通歐亞陸路，促進貿易與貨物流通。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-11", "no": 11, "c": "c13", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "隨著元代版圖拓展，來自中亞、西亞的哪一文化影響中國天文曆法、宗教、醫藥等的發展？", "o": ["大遼", "印度", "占城", "伊斯蘭"], "a": 3, "e": "元代大批穆斯林（回回）進入中國，伊斯蘭文化影響了天文曆法、宗教和醫藥。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-12", "no": 12, "c": "c11", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋代儒家學者融合佛學等思想，形成理學，其集大成者為何人？", "o": ["朱熹", "趙匡胤", "張擇端", "岳飛"], "a": 0, "e": "南宋朱熹集理學大成，著有《四書集注》。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-13", "no": 13, "c": "c12", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "北宋普遍將火藥應用在軍事上，後來哪一個民族將其改良應用，大幅改變了戰爭的型態？", "o": ["蒙古", "匈奴", "女真", "契丹"], "a": 0, "e": "蒙古西征時改良火藥武器，並把火藥傳到西亞、歐洲，改變了戰爭型態。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-14", "no": 14, "c": "c11", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋代理學出現，《四書集注》體現理學精神，此書更在哪個朝代成為科舉考試的定本？", "o": ["唐代", "北宋", "南宋", "元代"], "a": 3, "e": "《四書集注》在元代恢復科舉後成為考試定本，影響元、明、清三代。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-15", "no": 15, "c": "c12", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "北宋何人發明活字印刷術，不但改善以往印刷不能重新排版的缺點，更提高了印刷效率？", "o": ["商鞅", "朱熹", "畢昇", "張擇端"], "a": 2, "e": "北宋畢昇發明膠泥活字，可以拆開重新排版，提高印刷效率。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-16", "no": 16, "c": "c11", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(一)為朱熹《四書集注》古籍書影", "q": "圖(一)為中國某一個時期的學術精華，由內容判斷，其具有的價值意義應為下列何者？", "o": ["體現佛教中國化的精神", "集法家於大成的代表作", "彰顯亂世下的心靈寄託", "成為日後科舉考試定本"], "a": 3, "e": "《四書集注》是朱熹的理學代表作，元代起成為科舉考試的定本。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-17", "no": 17, "c": "c9", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "圖(二)的物件由元朝的「鈔券提舉司」專門負責印製，也有防偽的設置，但在後期因過度濫印，導致財政混亂。此物件的功用應為下列何者？", "o": ["驛站的通行證", "付款用的貨幣", "坊市的出入許可", "停靠市舶司證明"], "a": 1, "e": "元朝的「寶鈔」由鈔券提舉司印製，是付款用的紙幣；後期濫印，造成通貨膨脹、財政混亂。", "rep": false, "img": "chao-zhongtong", "fh": "", "maps": [], "chk": ""}, {"id": "h3-18", "no": 18, "c": "c5", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(三)為橫跨歐亞的蒙古四大汗國與元朝疆域圖", "q": "毛毛在某部電影中看到如圖(三)的地圖，請問這部電影的片名最可能是下列何者？", "o": ["《趙匡胤之五代終章》", "《風波亭之岳飛末路》", "《鐵騎北來之女真族亂》", "《風馳草原之蒙古帝國》"], "a": 3, "e": "疆域橫跨歐亞、分成四大汗國與元朝，代表的是蒙古帝國。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-19", "no": 19, "c": "c10", "src": "自修第 24 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "2021 年，中國泉州以「宋元中國的世界海洋商貿中心」名義申請世界遺產獲得通過，申報的 22 個景點項目包括生產基地、交通網絡、整體格局等，展示了泉州在經濟文化發展的貢獻。下列何者最可能是上述世界遺產景點？", "o": ["萬里長城", "雲岡石窟", "白鹿洞書院", "市舶司遺址"], "a": 3, "e": "泉州是宋元時最重要的商港，設有市舶司，市舶司遺址最符合「海洋商貿中心」。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-20", "no": 20, "c": "c1", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(四)為小說角色蕭峰簡介卡：曾與遼國皇帝結為兄弟，最後為阻止大遼入侵而犧牲", "q": "僑宏覺得歷史很困難，很多人物分不清楚，在歷史老師推薦他閱讀金庸武俠小說後，觸發他學習歷史的興趣，圖(四)是他最喜歡的主角簡介。該主角應該是生活在下列何人所創立的朝代？", "o": ["趙匡胤", "鐵木真", "張擇端", "忽必烈"], "a": 0, "e": "蕭峰與遼國皇帝結拜、阻止遼國南侵，時代是北宋與遼並立的時期；北宋由趙匡胤建立。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-21", "no": 21, "c": "c8", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(五)為《清明上河圖》街道商家、酒樓與市民活動局部圖", "q": "圖(五)為張擇端的《清明上河圖》局部，此圖最大的貢獻應為下列何者？", "o": ["回味宋代宮廷樓閣，體現皇宮權貴奢華生活", "保留南宋臨安城市風貌，作為研究南宋史料", "記載當代科技成就，堪稱中國傳統科技指南", "描繪宋代庶民城市生活，刻畫當時民俗風情"], "a": 3, "e": "《清明上河圖》描繪北宋汴京的街市與庶民生活，是了解宋代城市生活的重要史料。不是南宋臨安。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-22", "no": 22, "c": "c10", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "「帝國跨歐亞兩洲，陸上驛道通暢，加上對於西域色目商人的優惠，招徠大批商人。海上貿易亦漸興盛，馬可波羅筆下的泉州，儼然為全世界數一數二的商港。」上述是指哪一個政權統治時的景象？", "o": ["北宋", "南宋", "遼國", "元代"], "a": 3, "e": "帝國跨歐亞、陸上驛道、優待色目商人、馬可波羅筆下的泉州，都指元代。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-23", "no": 23, "c": "c6", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(六)為元世祖忽必烈畫像與其自述平西夏、滅金國、降江南、統一中國之對白", "q": "昕諭觀看「歷史啟示錄」節目時，在節目內容中看到如圖(六)的人物介紹。由圖中內容判斷，該人物會有下列哪一項作為？", "o": ["迫使漢人政權訂下盟約", "實施差別待遇種族政策", "攻滅汴京擄走漢人皇帝", "發動三次西征遠達歐洲"], "a": 1, "e": "平西夏、滅金、降江南、統一中國的是元世祖忽必烈，他實施差別待遇的種族政策。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-24", "no": 24, "c": "c4", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "表(一)整理北宋與南宋的建國者、建都汴京與臨安，以及政權更替原因「？」", "q": "佑誠將宋代政權加以比較，整理如表(一)。表中的「？」應該填入下列何者？", "o": ["匈奴入侵", "澶淵之盟", "蒙古西征", "靖康之禍"], "a": 3, "e": "北宋（都汴京）因靖康之禍滅亡，宋室南渡成為南宋（都臨安）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-25", "no": 25, "c": "c5", "src": "自修第 25 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(七)引文卡片：「他在乾旱草原縮小之時打敗南方部落稱霸天下...統合作龐大的征服部隊，徹底撼動亞洲與歐洲」", "q": "毓韻老師為了教學，常上網搜尋與課程相關新聞，並在個人粉絲頁上分享。這天她又貼了如圖(七)的內容跟學生分享。由書中介紹的可知，該人物應為下列何人？", "o": ["鐵木真", "忽必烈", "趙匡胤", "岳飛"], "a": 0, "e": "統合草原部落、組成龐大征服軍、撼動亞洲與歐洲的是鐵木真（成吉思汗）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-26", "no": 26, "c": "c8", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "張子提出身書香世家，世居汴京，他家左鄰是全京城最有名的表演場所，右舍則為他最常去的雜貨店，晚上還有夜市可以逛。上述居住型態的出現，與下列何者關係最為密切？", "o": ["澶淵之盟簽訂", "市舶司的設立", "坊市制度廢除", "政府廣設驛站"], "a": 2, "e": "住家旁就是表演場所、雜貨店，晚上還有夜市，表示坊市制度廢除，住宅區和商業區不再分開。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-27", "no": 27, "c": "c4", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(八)為岳飛《滿江紅》詞句「壯志飢餐胡虜肉，笑談渴飲匈奴血」之圖卡", "q": "以盡忠報國著稱的岳飛，曾留下一首著名的詞《滿江紅》，圖(八)為其節錄。圖中的「胡虜」指的是哪一個草原民族？", "o": ["女真", "蒙古", "契丹", "匈奴"], "a": 0, "e": "岳飛是南宋抗金名將，「胡虜」指建立金國的女真族。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-28", "no": 28, "c": "c6", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "表(二)為元朝四大族群特徵表：甲為受金統治各民族、乙為地位最高、丙為擅長理財擔任財政、丁為受南宋統治各民族", "q": "歐洲人對中國產生興趣，有一部分是因為《馬可波羅遊記》，遊記中敘述威尼斯人馬可波羅曾到中國經商，並受到元世祖忽必烈的重用。他最有可能是屬於表(二)中哪一類人？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "馬可波羅來自歐洲，屬於色目人；色目人擅長理財、擔任財政官員，就是丙。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-29", "no": 29, "c": "c10", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "宋臣是宋代的商人，在他的生活當中，不可能有下列何種體驗？", "o": ["在早熟稻收割之前先和農民談好價格", "利用政府所設置的驛站前往西亞貿易", "發現市面上的活字印刷書籍愈來愈多", "準備紙鈔和硬幣打算到汴京擺攤賺錢"], "a": 1, "e": "驛站是元代才廣設的，宋代商人不可能利用政府驛站去西亞。早熟稻、活字印刷書、紙鈔在宋代都看得到。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-30", "no": 30, "c": "c4", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(九)引述海上之盟約定：雙方攻打遼國，事成後乙國將歲幣轉給甲國，甲國歸還燕雲十六州", "q": "圖(九)為甲、乙兩國為了聯合力量夾攻敵國而簽訂的軍事盟約，日後，敵國覆滅，但也為乙國滅亡埋下伏筆。根據盟約內容判斷，簽署此盟約的甲、乙兩國分別為哪一政權？", "o": ["金、北宋", "遼、金", "西夏、南宋", "南宋、蒙古"], "a": 0, "e": "「海上之盟」是金與北宋聯合攻遼；遼滅亡後，金南侵滅了北宋。所以甲是金、乙是北宋。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-31", "no": 31, "c": "c13", "src": "自修第 26 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(十)為古籍《回回藥方雜卷之下 咳嗽門》書頁", "q": "因新冠肺炎流行全球，除了現代醫學的努力，傳統中醫也主打提升免疫力的藥方，一起加入抗疫的行列，喜德老師就在古籍中尋找到圖(十)「咳嗽門」的治療方法。此藥方具有何處的特色？", "o": ["阿拉伯", "越南", "印度", "日本"], "a": 0, "e": "《回回藥方》融合阿拉伯醫學，帶有阿拉伯（伊斯蘭）特色。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-32", "no": 32, "c": "c5", "src": "自修第 28 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "", "q": "中國某個朝代首都的描述：「汗八里城內外人戶繁多，有各地來往之色目人，甚至有基督教及伊斯蘭教者占卜吉凶禍福。從汗八里城通往各省的道路上，每隔二十五至三十英里，就有房舍接待過往的使臣或商人，稱作驛站。汗八里有一所製幣局，製造一種流通於全國的貨幣，連外國商人帶著金銀、寶石、皮革到大汗面前出售，大汗也是用紙幣來付帳。」由上文中內容可知應是對哪一個朝代首都的描述？", "o": ["東漢", "唐代", "北宋", "元代"], "a": 3, "e": "色目人、驛站、全國流通的紙幣、「大汗」，都指元代首都大都（汗八里）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-33", "no": 33, "c": "c5", "src": "自修第 28 頁（115上試題寶典評量）", "st": "自修", "ctx": "中國某個朝代首都的描述：「汗八里城內外人戶繁多，有各地來往之色目人，甚至有基督教及伊斯蘭教者占卜吉凶禍福。從汗八里城通往各省的道路上，每隔二十五至三十英里，就有房舍接待過往的使臣或商人，稱作驛站。汗八里有一所製幣局，製造一種流通於全國的貨幣，連外國商人帶著金銀、寶石、皮革到大汗面前出售，大汗也是用紙幣來付帳。」由上文中內容可知應是對哪一個朝代首都的描述？", "fig": "", "q": "由上文中內容可知「汗八里」應位於圖(五)何處？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "汗八里就是元大都（今北京），在圖中是甲。", "rep": false, "img": "q33", "fh": "", "maps": [], "chk": ""}, {"id": "h3-34", "no": 34, "c": "c3", "src": "自修第 28 頁（115上試題寶典評量）", "st": "自修", "ctx": "", "fig": "圖(六)：宋元疆域演變圖之一。乙國在中原，北方是遼，西北是西夏。", "q": "自從唐帝國衰亡後，亞洲北部先後興起了數個草原民族建立的國家，相繼成為主導東亞地區的重要力量，圖(六)為宋元疆域演變圖。根據所學判斷，圖(六)中乙國與周邊國家的關係為何？", "o": ["採取和親政策，維繫彼此友善關係", "積極派兵征伐鄰國，戰爭連年不休", "每年給予鄰國財物，維持百年和平", "稱霸東亞，鄰國紛紛表歸順推為盟主"], "a": 2, "e": "乙是北宋，與遼簽訂澶淵之盟，每年給歲幣，換來一百多年和平。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-35", "no": 35, "c": "c8", "src": "自修第 36 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "", "q": "咪咪正在撰寫一篇研究北宋汴京庶民生活的報告，她希望探討北宋的城市生活、各行各業、各種階級和街道房舍。你會建議她參考哪一份史料？", "o": ["《清明上河圖》", "《四書集注》", "《萬國來朝圖》", "《幾何原本》"], "a": 0, "e": "《清明上河圖》描繪北宋汴京的城市生活、各行各業和街道房舍。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-36", "no": 36, "c": "c10", "src": "自修第 36 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "", "q": "宋元時期，中國船隻出海必須取得某個機構發予的「公憑」，其為記載貨物相關內容的出海執照，也是東亞各港口驗證商船的依據。發行「公憑」的機構最可能為下列何者？", "o": ["驛站", "專業市鎮", "郊", "市舶司"], "a": 3, "e": "市舶司管理海上貿易，發給出海執照「公憑」，也負責檢查商船。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-37", "no": 37, "c": "c9", "src": "自修第 36 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "", "q": "《馬可波羅遊記》中曾說：「這種東西的製造，無論是規格和認可手續，都和純金幣或純銀幣那樣鄭重可信。因為有許多特別任命的官員，不僅在每張紙上具名，還要蓋章，當他們依次完成後，最後再由一個受皇帝任命的官員，將他所保管的御印，蓋於其上。……它可以用来購買任何所需的商品，有如純金的貨幣那樣。」上述描述的東西應為下列何者？", "o": ["銅幣", "驛站", "白銀", "寶鈔"], "a": 3, "e": "馬可波羅描述的是元代紙幣「寶鈔」，由官方蓋印發行，可以購買任何商品。", "rep": true, "img": "", "fh": "", "maps": ["chao-zhongtong"], "chk": ""}, {"id": "h3-38", "no": 38, "c": "c6", "src": "自修第 36 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "表(二)列出蒙古人、色目人考2場且題目易，漢人、南人考3場且題目難", "q": "表(二)為某朝代科舉的細則，請判斷這應該是哪一朝代的科舉制度？", "o": ["宋代", "元代", "明代", "清代"], "a": 1, "e": "蒙古人、色目人考試場次少、題目易，漢人、南人場次多、題目難，是元代差別待遇的種族政策。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-39", "no": 39, "c": "c3", "src": "自修第 37 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "圖(三)標示北方為遼、西北為西夏，北宋與遼之間有澶淵之盟、歲幣往來與兄弟相稱箭頭", "q": "圖(三)是中國某一個時代的情勢圖，由圖中的內容判斷，該圖的主題最可能為下列何者？", "o": ["東周的諸侯爭霸", "漢初的和親政策", "北宋的國際關係", "明末的對外貿易"], "a": 2, "e": "圖中有遼、西夏、北宋，還有澶淵之盟、歲幣、兄弟相稱，主題是北宋的國際關係。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-40", "no": 40, "c": "c4", "src": "自修第 37 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "表(三)遊戲目標欄位寫道：「在1127年金兵入侵之前得到聖旨打敗奸臣，以避免國家滅亡」", "q": "阿修對遊戲很有興趣，某日他在電玩展中，看到一款復古的任天堂紅白機遊戲《水滸傳·天命之誓》，表(三)為其遊戲的相關內容。此遊戲的設計應是以哪一個朝代為背景？", "o": ["北宋", "南宋", "元代", "明代"], "a": 0, "e": "1127 年金兵入侵滅北宋（靖康之禍），遊戲要在這之前打敗奸臣，所以背景是北宋末年。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-41", "no": 41, "c": "c5", "src": "自修第 37 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "圖(四)為橫跨歐亞的蒙古西征與元朝領土擴張地圖", "q": "圖(四)為某個朝代在半個世紀內擴張的領土，此朝代統治的民族複雜，遠超過其他時期，可說是中國史上最獨特的時代。上述的朝代最有可能是下列何者？", "o": ["漢代", "唐代", "元代", "明代"], "a": 2, "e": "半世紀內擴張成橫跨歐亞的領土、統治的民族最複雜，是元代（蒙古）。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-42", "no": 42, "c": "c10", "src": "自修第 37 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "圖(五)為穿越小說《新宋》封面與介紹，講述現代大學生穿越回北宋進行改革", "q": "根據圖(五)這部小說的介紹來看，小說主角石越穿越後的境遇，以下列哪一項最符合史實？", "o": ["跟著友人到政府廣設的驛站稍作休息", "在邊境做生意時，受到蒙古人的刁難", "天災頻仍且糧食不足，引發流寇之禍", "在廣州的市舶司引導漢人與外商貿易"], "a": 3, "e": "主角穿越到北宋。北宋已在廣州設市舶司；廣設驛站是元代，蒙古刁難是南宋末以後，流寇之禍是明末。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-43", "no": 43, "c": "c7", "src": "自修第 37 頁（115上試題寶典評量二次段考）", "st": "自修", "ctx": "", "fig": "", "q": "《宋史》：「大中祥符五年（1012年）五月戊辰，帝以江、淮、兩浙稍旱即水田不登，遣使就福建取占城稻三萬斛，分給三路為種，擇民田之高仰者蒔之，蓋旱稻也。」上文中的農產品應來自圖(六)中何處？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "占城在今越南，圖(六) 中位在中南半島越南一帶的是乙。", "rep": false, "img": "q43", "fh": "", "maps": [], "chk": ""}, {"id": "h3-44", "no": 44, "c": "c4", "src": "講義第 33 頁（115上教學式講義學習即時通 3-1）", "st": "講義", "ctx": "", "fig": "", "q": "宋朝根據首都及疆域的變遷，可細分為北宋與南宋，而導致王朝首都及疆域的改變為哪一事件？", "o": ["澶淵之盟", "蒙古西征", "靖康之禍", "遼國取得燕雲十六州"], "a": 2, "e": "靖康之禍使北宋滅亡、宋室南遷，首都由汴京改為臨安，疆域縮到淮河以南。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-45", "no": 45, "c": "c6", "src": "講義第 33 頁（115上教學式講義學習即時通 3-1）", "st": "講義", "ctx": "", "fig": "", "q": "種族歧視最易引發政治、社會不安，中國歷史上哪一朝代因為實行差別待遇的種族政策而導致衰亂？", "o": ["北宋", "南宋", "元代", "明代"], "a": 2, "e": "元代實施差別待遇的種族政策，引起漢人、南人強烈不滿，是元朝衰亡的重要原因。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-46", "no": 46, "c": "c3", "src": "講義第 33 頁（115上教學式講義學習即時通 3-1）", "st": "講義", "ctx": "", "fig": "", "q": "11 世紀初，北宋與哪一個國家簽訂「澶淵之盟」，此後兩國維持了一百多年的和平？", "o": ["遼國", "西夏", "金國", "蒙古"], "a": 0, "e": "澶淵之盟是北宋與遼（契丹）簽訂的。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-47", "no": 47, "c": "c8", "src": "講義第 35 頁（115上教學式講義學習即時通 3-2）", "st": "講義", "ctx": "", "fig": "", "q": "宋代商業非常發達，下列何者的出現說明宋代已取消過去坊市制度，沒有營業時間及地點的限制？", "o": ["夜市", "驛站", "市舶司", "紙幣"], "a": 0, "e": "夜市出現，代表商業不再受營業時間限制，是坊市制度瓦解的證據。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-48", "no": 48, "c": "c10", "src": "講義第 35 頁（115上教學式講義學習即時通 3-2）", "st": "講義", "ctx": "", "fig": "", "q": "宋元時期對外貿易發達，當時設置何種機構負責管理商船、檢查入港的貨物，以及徵稅等事宜，性質如同今日的海關？", "o": ["郊商", "市舶司", "洋行", "驛站"], "a": 1, "e": "市舶司負責管理商船、檢查入港貨物、徵稅，性質像今天的海關。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-49", "no": 49, "c": "c10", "src": "講義第 35 頁（115上教學式講義學習即時通 3-2）", "st": "講義", "ctx": "", "fig": "", "q": "下列哪一個民族在各地廣設「驛站」，提供國家信使、官員與旅人歇息的處所，促使歐亞國際貿易體系隨之成形？", "o": ["契丹人", "突厥人", "女真人", "蒙古人"], "a": 3, "e": "蒙古人（元代）廣設驛站，讓歐亞國際貿易體系成形。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-50", "no": 50, "c": "c10", "src": "講義第 35 頁（115上教學式講義學習即時通 3-2）", "st": "講義", "ctx": "", "fig": "", "q": "宋代國際貿易以海陸為主，主要的貿易港口有哪些？", "o": ["汴京、臨安", "廣州、泉州", "大都、占城", "上海、廈門"], "a": 1, "e": "宋代主要的對外貿易港口是廣州、泉州，都設有市舶司。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-51", "no": 51, "c": "c11", "src": "講義第 36 頁（115上教學式講義學習即時通 3-3）", "st": "講義", "ctx": "", "fig": "", "q": "下列哪一個王朝實施文人政治，社會文風興盛，並促使儒家學者融合佛學等思想，形成「理學」？", "o": ["唐代", "元代", "宋代", "漢代"], "a": 2, "e": "宋代實施文人政治、文風興盛，儒家學者融合佛學等思想，形成理學。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-52", "no": 52, "c": "c12", "src": "講義第 36 頁（115上教學式講義學習即時通 3-3）", "st": "講義", "ctx": "", "fig": "", "q": "下列哪項中國科技改善以往不能重新排版的缺點，可自由組字，減少刻字錯誤，提高了製作書籍的效率？", "o": ["火藥", "造紙術", "指南針", "活字印刷術"], "a": 3, "e": "活字印刷術可以自由組字、重複排版，減少刻字錯誤，提高效率。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-53", "no": 53, "c": "c13", "src": "講義第 36 頁（115上教學式講義學習即時通 3-3）", "st": "講義", "ctx": "", "fig": "", "q": "宋代因對外貿易發達，伊斯蘭教的商人東來貿易者眾多，導致哪一宗教隨之廣泛傳播？", "o": ["道教", "佛教", "基督教", "伊斯蘭教"], "a": 3, "e": "伊斯蘭教商人大量東來，伊斯蘭教也隨之傳播（例如興建清真寺）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-54", "no": 54, "c": "c6", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "來自西域的飛雷神，在元代的朝廷中擔任財政稅務官職，當時的他應屬於哪一個種族等級？", "o": ["蒙古人", "色目人", "漢人", "南人"], "a": 1, "e": "來自西域、在元朝擔任財政稅務官職，屬於色目人。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-55", "no": 55, "c": "c8", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "北宋時家住汴京的小瑜，她家左鄰是全京城最有名的正店（酒樓），右舍則為她最常去的客棧，走幾步路便到汴京城最大的客棧，閒時還可以到街上聽說書。這種生活及居住型態的出現，與下列何者關係最密切？", "o": ["紙幣的發行", "驛站的廣設", "外族的侵略", "坊市制度的廢除"], "a": 3, "e": "住家旁就是酒樓、客棧，還能上街聽說書，是坊市制度廢除後住商混合的景象。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-56", "no": 56, "c": "c12", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "在某本航海日誌裡寫著：「我們靠太陽、星辰辨別方位，當天候不佳時，利用指南針，便不至於迷失在茫茫大海中。」根據上述內容判斷，此日誌最早應出現於哪一時期？", "o": ["秦漢", "隋唐", "宋元", "明清"], "a": 2, "e": "指南針用於航海始於宋代，宋元時期普遍應用。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-57", "no": 57, "c": "c8", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "2024 年臺北華山 1914 文化創意產業園區舉辦了「會動的清明上河圖」展覽，透過投影技術和日夜循環的動態效果，讓畫中的人物與場景動了起來，吸引許多民眾前往體驗古代市井風貌。參觀的民眾可透過此幅圖來了解中國哪一朝代的城市生活？", "o": ["漢代", "唐代", "宋代", "元代"], "a": 2, "e": "《清明上河圖》描繪北宋汴京，可以了解宋代的城市生活。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-58", "no": 58, "c": "c4", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "表(一)：甲 北宋→遼國；乙 南宋→金國；丙 西夏→蒙古；丁 金國→西夏", "q": "表(一)是曉華整理 11～13 世紀東亞地區政權的勢力消長，表中箭頭的左方為被滅亡的國家。依此資料判斷，表中的哪一個選項完全正確？", "o": ["甲", "乙", "丙", "丁"], "a": 2, "e": "西夏被蒙古所滅，所以丙正確。遼被金滅、金被蒙古滅、北宋被金滅，所以甲、乙、丁都錯。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-59", "no": 59, "c": "c4", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "南宋將領岳飛寫下《滿江紅》：「靖康恥，猶未雪。臣子恨，何時滅！……」搭配著悲壯激昂的曲調，至今仍不斷傳唱著。岳飛詞中的「靖康恥」是指下列何者？", "o": ["北宋君臣遭女真族所俘", "蒙古先後發動三次西征", "宋真宗支付歲幣給遼國", "胡人建國導致晉室南遷"], "a": 0, "e": "「靖康恥」指 1127 年金（女真）攻陷汴京，俘虜徽、欽二帝，北宋滅亡。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-60", "no": 60, "c": "c8", "src": "講義第 38 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "剛加班回來的爸爸提議說：「今天晚上我們到夜市吃蚵仔煎、買衣服。」壯壯覺得有「夜市」實在很方便。「夜市」是從哪一個朝代開始出現？", "o": ["唐代", "宋代", "元代", "明代"], "a": 1, "e": "宋代坊市制度瓦解、取消夜禁，夜市從宋代開始出現。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-61", "no": 61, "c": "c8", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "史學家黃仁宇認為：「從物質生活來講，12 世紀的中國，無疑的已領先世界。」這主要是針對宋代哪一項特色而提出的看法？", "o": ["兼容並蓄的多元文化", "統一幣制並通行全國", "科技發達與商業興盛", "開鑿運河使物資交流"], "a": 2, "e": "宋代科技發達（三大發明）、商業興盛（紙幣、夜市、海外貿易），物質生活領先世界。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-62", "no": 62, "c": "c7", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "北宋初年，自國外引進早熟稻，生長期僅 60 天即能收穫，耐旱且可種植於高地，使得稻米產量大增，成為當時最重要的糧食作物。上述的糧食作物是從圖(三)中何地引進中國的？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "早熟稻引自占城（今越南），圖(三) 中位在中南半島的是丁。", "rep": false, "img": "q62", "fh": "", "maps": [], "chk": ""}, {"id": "h3-63", "no": 63, "c": "c8", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "天成為南宋臨安人士，他的住家對面是全城最大的客棧，街尾則為他最常去的正店，這種居住型態的出現，與下列何者關係最為密切？", "o": ["不受坊市制度的限制", "成立市舶司加以管理", "驛站的設置", "紙幣的使用"], "a": 0, "e": "住家對面是客棧、街尾是酒樓，住商混合，是不再受坊市制度限制的結果。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-64", "no": 64, "c": "c10", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "世界著名經濟史學家貢德弗蘭克認為：「自 11 世紀和 12 世紀的宋代以來，中國的經濟在工業化、商業化、貨幣化和城市化方面遠遠超過世界其他地方。」若要證實上述學者的說法，可以下列宋代在經濟上的哪一事蹟加以說明？", "o": ["自印度引進早熟稻，糧食產量大增", "在廣州和泉州設有市舶司管理貿易", "理學思想進步，並傳至遼國與金國", "與鄰國長期對峙，海路貿易不發達"], "a": 1, "e": "宋代在廣州、泉州設市舶司，海上貿易發達，可證明商業化。早熟稻來自越南不是印度；理學傳到朝鮮、日本；宋代海路貿易其實很發達。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-65", "no": 65, "c": "c2", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "美惠閱讀一篇名為〈宋元時期國際的對抗與征服〉的文章，根據史實判斷，文章中最可能出現下列哪一項敘述？", "o": ["突厥族於唐末崛起，南下奪取燕雲十六州", "趙匡胤建立宋王朝，定都汴京，史稱為北宋", "契丹族攻陷汴京，擄走皇帝，史稱靖康之禍", "蒙古族全面信仰伊斯蘭教，統治亞洲北草原"], "a": 1, "e": "趙匡胤建宋、定都汴京，史稱北宋，正確。燕雲十六州被契丹取得；靖康之禍是女真造成；蒙古沒有全面信仰伊斯蘭教。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-66", "no": 66, "c": "c6", "src": "講義第 40 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "圖(四)為元代社會階級金字塔：甲蒙古人、乙色目人、丙漢人、丁南人", "q": "圖(四)說明元帝國統治下的社會階級，根據圖中資料判斷，世居杭州的絲綢商人應屬於哪一階級？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "杭州原屬南宋統治，元代時屬第四等「南人」，就是丁。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-67", "no": 67, "c": "c6", "src": "講義第 43 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "以下是中國某朝代首都的簡介：「這是一座依計畫興建的城市，城中可見基督教教堂、伊斯蘭教清真寺及佛教寺廟。朝廷聘用色目人擔任財政官員，並推行全國性紙幣政策，加上各地物資的集中，讓這座城市成為金融經濟中心。」上述城市最可能是指下列何者？", "o": ["東漢洛陽", "唐代長安", "北宋汴京", "元代大都"], "a": 3, "e": "城中有教堂和清真寺、色目人掌財政、推行全國紙幣，是元代大都。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-68", "no": 68, "c": "c12", "src": "講義第 43 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "西元 9 世紀初，中國發明的火藥只用於變戲法、放煙火等活動上；10～14 世紀，火藥已普遍作為軍事用途。這段期間，東亞各政權相互爭霸，戰爭非常頻繁，也激發了各國對火藥配方和火器的改良；到了 13 世紀時，隨著東亞草原民族向西擴張，火藥得以西傳。上文提及火藥開始普遍作為軍事用途，是由於下列哪一政權當時對火藥的改良？", "o": ["唐代", "宋代", "遼國", "金國"], "a": 1, "e": "宋代改良火藥並普遍用於軍事，後來經蒙古西征傳到西方。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-69", "no": 69, "c": "c8", "src": "講義第 43 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "", "fig": "", "q": "首都汴京的小康家庭，已習慣購買外食，當時的《東京夢華錄》一書便記錄了百餘家店鋪，其中餐飲店超過半數，顯示餐飲業的繁榮發達。京城中的餐館依等級可細分為「正店」、「腳店」與「分茶」三類。上文中提及促成當時庶民美食文化興起，與下列哪一政策的實行密切相關？", "o": ["膠泥活字版印刷術的發明", "實施差別待遇的種族政策", "重視文人政治，理學興起", "商業營業時間與地點不受限制"], "a": 3, "e": "店鋪林立、外食發達，是商業不再受營業時間和地點限制（坊市制度瓦解）的結果。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-70", "no": 70, "c": "c8", "src": "講義第 43 頁（115上教學式講義會考學力診斷）", "st": "講義", "ctx": "首都汴京的小康家庭，已習慣購買外食，當時的《東京夢華錄》一書便記錄了百餘家店鋪，其中餐飲店超過半數，顯示餐飲業的繁榮發達。京城中的餐館依等級可細分為「正店」、「腳店」與「分茶」三類。上文中提及促成當時庶民美食文化興起，與下列哪一政策的實行密切相關？", "fig": "", "q": "承上題，下列哪一史料最能呈現當時的庶民飲食文化？", "o": ["《四書集注》", "《回回藥方》", "《幾何原本》", "《清明上河圖》"], "a": 3, "e": "《清明上河圖》描繪汴京街市與各種店鋪，最能呈現庶民飲食文化。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-71", "no": 71, "c": "c5", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "13 世紀初，鐵木真和繼位者率領各部落發動三次西征，建立四大汗國。之後，蒙古族的發展過程為何？", "o": ["滅南宋，成為第一個統治中國的草原民族", "建立清朝，採取高壓與懷柔並行的策略", "與北宋簽訂「澶淵之盟」", "與南宋合作將金國滅亡"], "a": 0, "e": "蒙古西征後，忽必烈建立元朝，1279 年滅南宋，成為第一個統治全中國的草原民族。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-72", "no": 72, "c": "c3", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "宋元時期，東亞國際間對抗激烈，遼、金和蒙古相繼發動戰爭，各自曾在東亞稱霸一時，並促進了東亞與歐洲間的商貿關係和文化交流。下列關於此時期的敘述，何者正確？", "o": ["南宋聯金滅遼", "金國橫跨歐亞", "北宋聯蒙古滅遼", "北宋與遼稱兄道弟"], "a": 3, "e": "澶淵之盟約定宋遼以兄弟相稱。聯金滅遼的是北宋、聯蒙滅金的是南宋；橫跨歐亞的是蒙古。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-73", "no": 73, "c": "c4", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "表(一)：甲 北宋→女真；乙 遼國→女真；丙 西夏→蒙古；丁 金國→蒙古；戊 南宋→蒙古", "q": "表(一)為小茂上課時統整的筆記內容，表中所傳達的意涵為何？", "o": ["東亞經濟網絡的形成", "朝貢貿易體制的運作", "東亞勢力的對抗與消長", "伊斯蘭教世界與東亞的交流"], "a": 2, "e": "表中各政權相繼被滅（北宋、遼亡於女真；西夏、金、南宋亡於蒙古），呈現東亞勢力的對抗與消長。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-74", "no": 74, "c": "c3", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "《宋代大小事》一書中提到：「皇帝登上前線城樓督戰，結果士兵大呼萬歲，聲聞數十里，軍心大振，最後與敵方簽訂和平協議，雙方以兄弟相稱。」關於上文的敘述，下列何者正確？", "o": ["交戰雙方是南宋與金國", "該協議為「澶淵之盟」", "親自督戰的皇帝為宋太祖", "協議後，雙方再度爆發戰爭"], "a": 1, "e": "皇帝（宋真宗）親征督戰、簽和約並以兄弟相稱，就是澶淵之盟。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-75", "no": 75, "c": "c4", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "宋詞《滿江紅》提到：「壯志飢餐胡虜肉，笑談渴飲匈奴血」，該詞傳聞是岳飛的作品。按照時空背景判斷，詞中的「胡虜」及「匈奴」指的是下列何者？", "o": ["契丹族", "鮮卑族", "女真族", "蒙古族"], "a": 2, "e": "岳飛抗金，詞中的「胡虜」「匈奴」是借指女真族。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-76", "no": 76, "c": "c8", "src": "講義第 57 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "圖(一)為「瓦子春秋」演出企畫書：劇情介紹為宋代臨安城中市民生活情境", "q": "圖(一)是明洙籌備話劇表演的企畫書，由圖中內容推斷，下列哪一種情境最可能出現在表演中？", "o": ["夜市通宵達旦，各種貨物琳瑯滿目", "商家賣熱騰騰的烤玉米與烤番薯", "男子薙髮，身穿長袍馬褂", "民眾普遍使用半兩錢購物"], "a": 0, "e": "「瓦子」是宋代的娛樂場所，背景是宋代臨安，可見夜市通宵達旦。玉米、番薯明代才傳入；薙髮是清代；半兩錢是秦代。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-77", "no": 77, "c": "c4", "src": "講義第 58 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "表(二)章節目錄：第一章 戰禍下君臣南渡；第二章 盡忠報國的岳飛；第三章 朱熹理學集大成；第四章 蒙古南侵國祚亡", "q": "表(二)為某本中國歷史書籍的章節，由表中內容判斷，此書最可能是下列何者？", "o": ["《元代風雲》", "《南宋史話》", "《明代傳奇》", "《清代演義》"], "a": 1, "e": "君臣南渡、岳飛、朱熹、蒙古南侵，都是南宋的史事。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-78", "no": 78, "c": "c5", "src": "講義第 58 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "13 世紀時，蒙古人勢力崛起，統一中國，結束多政權並立的局面。下列哪一組政權或族群是被蒙古人所滅？", "o": ["契丹、西夏", "北宋、越南", "日本、女真", "南宋、女真"], "a": 3, "e": "蒙古滅了金（女真）與南宋。契丹（遼）是被金滅；北宋也是被金滅。", "rep": true, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-79", "no": 79, "c": "c5", "src": "講義第 58 頁（115上教學式講義二次段考評量）", "st": "講義", "ctx": "", "fig": "", "q": "歌曲〈成吉思汗〉中有以下歌詞：「1162 某個深夜，握著一塊血，口進世界，註定立大業。……種族、國界被他超越，忠誠是手中最硬的鐵。△打開一個時代，征服了所有，看你拜不拜。」由歌名及歌詞內容研判，上述的口、△應分別填入何者最為適當？", "o": ["朱元璋、大明", "趙匡胤、大宋", "康熙、大清", "鐵木真、蒙古"], "a": 3, "e": "1162 年出生、超越種族國界、開創新時代的是鐵木真，他建立了蒙古帝國。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-80", "no": 80, "c": "c10", "src": "講義評量單第 6 回第 1 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "下列何者在各地廣設「驛站」，促進了歐亞等地的貿易與貨物的流通？", "o": ["蒙古帝國", "唐朝", "秦朝", "漢朝"], "a": 0, "e": "蒙古帝國廣設驛站，促進歐亞貿易與貨物流通。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-81", "no": 81, "c": "c10", "src": "講義評量單第 6 回第 2 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "下列何者其功能類似今日海關，主要是管理商船、檢查入港的貨物，以及徵稅等事宜？", "o": ["絲路", "市舶司", "驛站", "坊市"], "a": 1, "e": "市舶司的功能類似今天的海關。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-82", "no": 82, "c": "c8", "src": "講義評量單第 6 回第 3 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "關於宋代的經濟與農業，下列敘述何者正確？", "o": ["紙幣尚未流通", "各地廣設驛站", "實施坊市制度", "此時夜市興盛"], "a": 3, "e": "宋代夜市興盛，正確。宋代已有紙幣（交子）；廣設驛站是元代；坊市制度在宋代已瓦解。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-83", "no": 83, "c": "c11", "src": "講義評量單第 6 回第 4 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "自哪一個朝代起，《四書集注》成為科舉考試的定本？", "o": ["隋代", "唐代", "宋代", "元代"], "a": 3, "e": "元代起，《四書集注》成為科舉考試的定本。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-84", "no": 84, "c": "c11", "src": "講義評量單第 6 回第 5 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "宋代理學思想傳入下列哪兩個地區，頗受重視？", "o": ["吐蕃、突厥", "西夏、大食", "朝鮮、日本", "蒙古、越南"], "a": 2, "e": "宋代理學傳入朝鮮、日本，影響深遠。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-85", "no": 85, "c": "c11", "src": "講義評量單第 6 回第 6 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "宋代重視文人政治，提倡儒學，而儒家學者融合下列何者思想形成「理學」？", "o": ["佛學", "科舉", "法學", "伊斯蘭文化"], "a": 0, "e": "理學是儒家學者融合佛學（以及道家）思想而形成的。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-86", "no": 86, "c": "c13", "src": "講義評量單第 6 回第 7 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "宋代因對外貿易發達，東來貿易者眾多，下列哪一宗教也隨之廣泛傳播？", "o": ["伊斯蘭教", "道教", "基督教", "佛教"], "a": 0, "e": "外國商人（阿拉伯、波斯）東來，伊斯蘭教也隨之傳播。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-87", "no": 87, "c": "c13", "src": "講義評量單第 6 回第 8 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "大批伊斯蘭教徒遷居中國，影響天文曆法、醫藥、宗教的發展是在下列何時？", "o": ["秦漢時期", "東晉時期", "隋唐時期", "宋元時期"], "a": 3, "e": "宋元時期大批伊斯蘭教徒遷入中國，影響了天文曆法、醫藥和宗教。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-88", "no": 88, "c": "c12", "src": "講義評量單第 6 回第 9 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "宋代指南針經下列何者傳入歐洲？", "o": ["蒙古人", "契丹人", "女真人", "阿拉伯人"], "a": 3, "e": "指南針經由阿拉伯人傳入歐洲。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-89", "no": 89, "c": "c10", "src": "講義評量單第 6 回第 10 題（115上教學式講義隨堂評量單）", "st": "講義", "ctx": "", "fig": "", "q": "驛站促進了哪兩地的貿易與貨物流通？", "o": ["亞洲、非洲", "歐洲、非洲", "歐洲、亞洲", "美洲、亞洲"], "a": 2, "e": "驛站連通歐亞，促進歐洲與亞洲的貿易。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-90", "no": 90, "c": "c6", "src": "考卷 114上翰林社會2上A卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "蒙古帝國藉由自身強大的軍事優勢及領導策略向外擴張，使疆域一度橫跨歐亞兩洲。蒙古所建的元朝是歷史上第一個由少數民族建立的統一政權，然而與其他朝代相比國祚不到百年就迅速覆滅。上述朝代的衰亡與下列何者密不可分？", "o": ["外患頻仍", "種族歧視", "權臣叛變", "倭寇侵擾"], "a": 1, "e": "元代實施差別待遇的種族政策，引發民族不滿、民變四起，國祚不到百年。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-91", "no": 91, "c": "c4", "src": "考卷 114上翰林社會2上A卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋室南遷後，由於在戰事上的需求明顯提高，故對武將的薪資與待遇比北宋時來得高，甚至是歷代武將中相對優厚的一朝，例如名將岳飛除了俸祿外，朝廷還會額外賞賜金銀、土地等。上述名將所抵禦的是下列哪一外族？", "o": ["匈奴", "突厥", "契丹", "女真"], "a": 3, "e": "岳飛是南宋抗金名將，抵禦的是女真（金）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-92", "no": 92, "c": "c3", "src": "考卷 114上翰林社會2上A卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋朝在與他國訂立澶淵之盟後，中國的國際地位有很大變化。關於上述契約的訂立，下列敘述何者正確？", "o": ["訂約雙方以父子互稱", "訂約後宋朝隨即滅亡", "宋朝的訂約對象為女真族", "訂約後中國與他國建立對等關係"], "a": 3, "e": "澶淵之盟宋遼以兄弟相稱，中國開始與外族建立對等關係。訂約對象是契丹，訂約後維持百年和平。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-93", "no": 93, "c": "c8", "src": "考卷 114上翰林社會2上A卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋朝人離不開外賣文化，宋孝宗曾於一次節慶期間，點了外賣「李婆婆魚羹」、「南瓦張家圓子」，連皇帝都愛點外賣，民眾當然也跟風流行。根據史料可知宋代居住在汴京做生意的小康家庭，已經習慣購買外食了。若我們欲深入研究上述庶民生活，可參考下列何人的作品？", "o": ["張擇端", "鐵木真", "朱熹", "岳飛"], "a": 0, "e": "張擇端的《清明上河圖》描繪北宋汴京的庶民生活。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-94", "no": 94, "c": "c11", "src": "考卷 114上翰林社會2上A卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "圖(一)評論字卡：「宋朝雖然是個軍事不振的朝代...卻是中國歷史上最有人文精神、最有思想的朝代」", "q": "圖(一)是李教授閱讀《我們為什麼愛宋朝》一書之後的評論，根據圖中敘述判斷，上述朝代提倡下列哪一思想？", "o": ["理學", "封建", "法學", "民主"], "a": 0, "e": "宋代雖然軍事不振，但人文思想發達，代表的學術思想是理學。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-95", "no": 95, "c": "c7", "src": "考卷 114上翰林社會2上A卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "北宋引進早熟稻，使稻米的產量增加，成為最重要的糧食作物。上述引進的作物，其原產於圖(二)中何地？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "早熟稻原產於占城（今越南），圖(二) 中丁在越南。", "rep": false, "img": "q95", "fh": "", "maps": [], "chk": ""}, {"id": "h3-96", "no": 96, "c": "c11", "src": "考卷 114上翰林社會2上A卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "從秦漢歷經隋唐，直到宋元時期，中國文化外傳，對周邊地區的影響深遠，尤其是下列哪些地區深受宋代理學思想的影響？", "o": ["朝鮮、日本", "朝鮮、越南", "越南、吐蕃", "吐蕃、日本"], "a": 0, "e": "宋代理學傳入朝鮮、日本，影響深遠。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-97", "no": 97, "c": "c6", "src": "考卷 114上翰林社會2上A卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "「回回醫人」主要是來自中亞或西亞地區具備醫學知識的穆斯林，在元朝中內擔任醫師、藥師等職務，善用草藥、礦物藥，熟悉解剖學，帶來不同於傳統中醫的觀念與技術。上述的「回回醫人」在該朝代內屬於哪一階級？", "o": ["蒙古人", "色目人", "漢人", "南人"], "a": 1, "e": "來自中亞、西亞的穆斯林，在元代屬於色目人。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-98", "no": 98, "c": "c10", "src": "考卷 114上翰林社會2上A卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "14 世紀時，為進行貿易而東來的阿拉伯商人，在前往中國首都的路上，發現頻繁裝置歇息的處所，外國使節、公務往來的官員均在此進出。上述處所為何？", "o": ["驛站", "市舶司", "坊市", "夜市"], "a": 0, "e": "14 世紀是元代，通往首都的路上設有驛站，供使節、官員歇息。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-99", "no": 99, "c": "c12", "src": "考卷 114上翰林社會2上A卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "霹靂砲最早記載於宋代兵書《武經總要》，外殼多為陶或鐵製，內裝黑火藥，點燃後能爆炸發出巨大聲響與殺傷力，是宋代以防作戰時的重要火藥武器。該科技發展後經哪一民族改良後傳入歐洲？", "o": ["阿拉伯人", "蒙古人", "葡萄牙人", "西班牙人"], "a": 1, "e": "宋代的火藥武器，後來經蒙古西征改良並傳入歐洲。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-100", "no": 100, "c": "c12", "src": "考卷 114上翰林社會2上A卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國科技發明——指南針運用於航海，奠定遠洋航行的基礎。經由下列何者傳入歐洲，有助於新航路的發現？", "o": ["阿拉伯人", "蒙古人", "色目人", "女真人"], "a": 0, "e": "指南針經阿拉伯人傳入歐洲，有助於新航路的發現。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-101", "no": 101, "c": "c1", "src": "考卷 114上翰林社會2上A卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "「燕雲十六州」一詞出自於《宋史》，範圍包括今日中國的北京、天津海河以北，以及山西、河北北部，自古以來為中原政權的國防重地，唐朝滅亡後，該地被崛起的哪一草原民族所控制？", "o": ["契丹", "西夏", "女真", "蒙古"], "a": 0, "e": "唐亡後的五代時期，後晉石敬瑭把燕雲十六州割給契丹（遼）。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-102", "no": 102, "c": "c10", "src": "考卷 114上翰林社會2上A卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "圖(三)為花蓮崇德遺址出土宋代銅錢「熙寧元寶」之新聞圖卡", "q": "圖(三)新聞中提及的宋代銅錢，不僅出現在花蓮沿海，在越南、印尼、新加坡等國，甚至是東非沿岸也曾出土此文物，顯示宋代國際貿易發達，這些貨幣可能是從當時中國的何地輸出的？", "o": ["大連、青島", "西域、大都", "天津、上海", "泉州、廣州"], "a": 3, "e": "宋代對外貿易港口以泉州、廣州為主，銅錢從這些港口輸出到海外。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-103", "no": 103, "c": "c14", "src": "考卷 114上翰林社會2上A卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷代北方草原民族擾侵中國，以宋代時東亞國際間的對抗最為激烈，有數個草原民族都曾稱霸東亞，下列哪一族不是宋代的主要外患？", "o": ["蒙古", "女真", "突厥", "契丹"], "a": 2, "e": "宋代的主要外患是遼（契丹）、西夏（党項）、金（女真）、蒙古；突厥是隋唐時期的外患。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-104", "no": 104, "c": "c2", "src": "考卷 114上翰林社會2上A卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋朝長期的積弱不振，始終無法形成強大的軍事力量來對抗外患和強敵。上述與宋朝建國後採取下列哪一政策有關？", "o": ["種族歧視", "重文輕武", "偏安江南", "割讓燕雲十六州"], "a": 1, "e": "宋代重文輕武、強幹弱枝，雖然避免武將割據，卻造成國防積弱。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-105", "no": 105, "c": "c6", "src": "考卷 114上翰林社會2上A卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "林德是元代世居臨安的讀書人，為想功成名就，明知自己屬於受歧視的族群，仍全力以赴苦讀儒家叢書。根據敘述判斷，林德在當時屬於哪一階級？", "o": ["蒙古人", "色目人", "南人", "漢人"], "a": 2, "e": "世居臨安（原南宋統治地區）、受到歧視，屬於第四等「南人」。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-106", "no": 106, "c": "c4", "src": "考卷 114上翰林社會2上A卷 卷6 第 2 題（跨課）", "st": "考卷", "ctx": "", "fig": "圖(一)為北宋、遼、西夏形勢圖；圖(二)為南宋、金、西夏形勢圖", "q": "圖(一)和圖(二)分別是兩宋形勢圖，圖(一)演變到圖(二)的關鍵史事為何？", "o": ["海禁政策", "蒙古西征", "澶淵之盟", "靖康之禍"], "a": 3, "e": "圖一是北宋與遼、西夏並立，圖二變成南宋與金對峙，關鍵是靖康之禍。", "rep": true, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-107", "no": 107, "c": "c8", "src": "考卷 114上翰林社會2上A卷 卷6 第 3 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "上海舉辦世界博覽會，中國館《清明上河圖》利用多媒體手法探討在長牆上，並使圖中的人物都動了起來。參觀的民眾可以透過這幅圖來了解中國哪一個朝代的生活面貌？", "o": ["宋人的城市生活", "大唐的繁華京城", "漢代的絲路經商", "元代的廣大疆域"], "a": 0, "e": "《清明上河圖》呈現宋代的城市生活。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-108", "no": 108, "c": "c5", "src": "考卷 114上翰林社會2上A卷 卷6 第 4 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "濬澤假日打電玩《世紀帝國Ⅱ》中世紀蒙古帝國，描述鐵木真一統一戰的蒙古民族，之後進入中國，一路從中國征戰到花剌子模、波希米亞等。上文敘述的是下列何人的事蹟？", "o": ["利瑪竇", "徐光啟", "忽必烈", "成吉思汗"], "a": 3, "e": "統一蒙古、一路征戰到花剌子模等地的是鐵木真，也就是成吉思汗。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-109", "no": 109, "c": "c4", "src": "考卷 114上翰林社會2上A卷 卷6 第 6 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "老師請班上的同學分組作業是找出古列朝代分裂的共同原因。下列何者最正確？[分組朝代：(一)西周→東周；(二)西晉→東晉；(三)北宋→南宋]", "o": ["外族入侵", "種族政策", "奪王篡位", "民變宦官"], "a": 0, "e": "西周→東周（犬戎入侵）、西晉→東晉（五胡亂華）、北宋→南宋（女真入侵），共同原因都是外族入侵。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-110", "no": 110, "c": "c6", "src": "考卷 114上翰林社會2上A卷 卷6 第 8 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "阿凱是某個朝代的讀書人，居住在江南一帶，他想參加科舉考試，卻因為當時種族政策的實施，導致考試題目較難、錄取率低；就算考上，也很難升遷到較高的職務。依上述判斷，阿凱屬於哪個朝代的人？", "o": ["漢代", "唐代", "宋代", "元代"], "a": 3, "e": "科舉題目較難、錄取率低、難以升遷，是元代對漢人、南人的差別待遇。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-111", "no": 111, "c": "c7", "src": "考卷 114上翰林社會2上A卷 卷6 第 10 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "自占城（今越南）引進早熟稻，使稻米產量大增，並逐漸成為重要的糧食作物。上述情況最早開始於下列何時？", "o": ["宋代", "元代", "明代", "清代"], "a": 0, "e": "占城稻（早熟稻）是在宋代引進的。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-112", "no": 112, "c": "c3", "src": "考卷 114上翰林社會2上A卷 卷6 第 15 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "中國古代為了對付北方草原民族的入侵，採取了多種措施，其中北宋真宗所採取的措施為何？", "o": ["給予歲幣", "和親政策", "結盟抗敵", "分封為王"], "a": 0, "e": "宋真宗簽訂澶淵之盟，採取每年給予遼國歲幣的方式。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-113", "no": 113, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "小櫻利用圖示學習宋代的歷史。下列四幅小櫻繪製的兩宋與遼、西夏、金對立形勢簡圖，何者有誤？", "o": ["圖(A)", "圖(B)", "圖(C)", "圖(D)"], "a": 2, "e": "遼在 1125 年被金所滅，南宋是 1127 年才建立，遼和南宋沒有同時存在，所以 (C) 錯誤。", "rep": false, "img": "q113", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-114", "no": 114, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "「北宋末年，由女真族建立的一個王朝，女真族首領完顏阿骨打在統一女真諸部後，建都立國。」上述指的是哪一個政權？", "o": ["西夏", "大理", "遼", "金"], "a": 3, "e": "完顏阿骨打統一女真各部，建立金國。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-115", "no": 115, "c": "c8", "src": "考卷 114上翰林社會2上B卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "圖(一)《清明上河圖》局部", "q": "圖(一)為張擇端的畫作「清明上河圖」，描繪北宋首都的繁榮，此場景貿易興盛的原因是因不再受何種政策的限制？", "o": ["郡縣制度", "廣設驛站", "坊市制度", "實施科舉"], "a": 2, "e": "《清明上河圖》裡商店臨街林立，是不再受坊市制度限制的景象。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-116", "no": 116, "c": "c12", "src": "考卷 114上翰林社會2上B卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "阿德是生活在北宋時期的商人，根據判斷，他很可能會有什麼樣的生活？", "o": ["透過活字印刷術印製大量書籍販賣", "為了準備科舉而研讀《四書集注》", "前往驛站與外國商人進行商業買賣", "聽聞蒙古軍在邊境與軍隊爆發衝突"], "a": 0, "e": "北宋畢昇發明活字印刷，北宋商人可能印書販賣。《四書集注》在元代才成為科舉定本；驛站是元代；蒙古是南宋時的外患。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-117", "no": 117, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "「元」是中國第一個以異族統一天下的朝代，其版圖遼闊，但是立足中原卻不到百年就滅亡了。下列何者不是其衰亡的原因？", "o": ["民變紛起", "財政混亂", "重文輕武", "帝位繼承紛爭不斷"], "a": 2, "e": "元朝衰亡的原因有民變、財政混亂、帝位紛爭；「重文輕武」是宋朝的國策。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-118", "no": 118, "c": "c14", "src": "考卷 114上翰林社會2上B卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "部分史家認為，宋代並非如此積弱不振，而是他們遭遇過的外患實力太過強大。北宋的主要外患不包括下列哪一部族？", "o": ["西夏", "蒙古", "契丹", "女真"], "a": 1, "e": "北宋的外患是遼、西夏、金；蒙古是南宋時期的外患。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-119", "no": 119, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "文謙是某個朝代的讀書人，居住在福建一帶。今年是他第一次參加科舉考試，但是受於當朝實施某種政策，導致考試題目較難、錄取率低；就算考上，也很難升遷到較高的職務。可知上述的政策為下列何者？", "o": ["推舉孝廉的任官標準", "偏重文人的基本國策", "宗法血緣的禮樂制度", "差別待遇的種族政策"], "a": 3, "e": "住在福建（原南宋地區）屬於南人，考試較難、錄取率低，這是差別待遇的種族政策。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-120", "no": 120, "c": "c11", "src": "考卷 114上翰林社會2上B卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "南宋學者集理學之大成，學術成就「致廣大，盡精微，綜羅百代」，被譽為繼孔孟之後影響最深遠的一代宗師，該學者是下列何人？", "o": ["畢昇", "岳飛", "朱熹", "張擇端"], "a": 2, "e": "南宋朱熹集理學大成，被譽為孔孟之後影響最深遠的學者。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-121", "no": 121, "c": "c7", "src": "考卷 114上翰林社會2上B卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代農業發展的重要關鍵，是新稻種的引進，加上耕作技術的改良，使得糧食產量大增。當時是由何處引進「早熟稻」？", "o": ["天竺（印度）", "占城（越南）", "大食（阿拉伯）", "呂宋（菲律賓）"], "a": 1, "e": "早熟稻是從占城（今越南）引進的。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-122", "no": 122, "c": "c1", "src": "考卷 114上翰林社會2上B卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "「長城自古以來是中國抵禦北方草原民族的重要防線，但在宋代建國以前，卻因『燕雲十六州』被割讓給外族，長城失去防禦功能，使得宋代備受威脅。」此外族為下列何族？", "o": ["契丹", "突厥", "女真", "蒙古"], "a": 0, "e": "燕雲十六州被割讓給契丹（遼），讓宋代失去長城防線。", "rep": true, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-123", "no": 123, "c": "c13", "src": "考卷 114上翰林社會2上B卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "翔翔在暑假時與家人一同去旅遊，看到了某個古蹟的介紹如下。根據內容判斷，翔翔旅遊的地點最可能為下列何者？[介紹：唐宋時期由番商建立，為目前中國保存最古老與完整的伊斯蘭教聖蹟之一...為宋朝宋軍進出駐地]", "o": ["長安", "汴京", "泉州", "洛陽"], "a": 2, "e": "番商建立的伊斯蘭教聖蹟（清淨寺）位在泉州。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-124", "no": 124, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代積弱不振，自建國後，即不斷遭受來自外族的威脅，最後並為其所滅。北宋和南宋分別亡於哪一外族？", "o": ["西夏、女真", "契丹、女真", "契丹、蒙古", "女真、蒙古"], "a": 3, "e": "北宋亡於女真（金），南宋亡於蒙古（元）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-125", "no": 125, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "蒙古以草原民族入主中國，憑藉的是強盛的武力。統一全國後，元帝國唯恐漢人不服，遂施行高壓的統治方式，因蒙古人自身文化水平較低，鑑於漢族傳統士人地位高、影響大，難以管理，便加以打壓。實施的種族政策以哪些等級受到較多的不平等待遇？", "o": ["蒙古人、色目人", "色目人、漢人", "漢人、南人", "蒙古人、南人"], "a": 2, "e": "漢人、南人受到較多不平等待遇，其中南人地位最低。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-126", "no": 126, "c": "c5", "src": "考卷 114上翰林社會2上B卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "真真整理歷史筆記，其中一個地方卻不小心遭到汙損。根據內容判斷，該民族應為下列何者？[筆記：13世紀，於今日河南的三峰山爆發戰爭，該部族以少量的軍隊打敗了北方金國...從此一蹶不振，再也無法強大，最終滅亡。]", "o": ["女真", "蒙古", "契丹", "突厥"], "a": 1, "e": "1232 年三峰山之戰，蒙古大敗金軍，金國從此一蹶不振，1234 年滅亡。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-127", "no": 127, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "1206 年，一個位於漠北的草原民族，建立起龐大的帝國，並開始向外擴張，先後攻滅西夏、金等國。下列關於這個民族的敘述，何者正確？", "o": ["與北宋簽訂澶淵之盟維持和平", "北宋時成吉思汗建立蒙古帝國", "統一中國後將人民分為四等級", "曾建立橫跨歐、亞、非的帝國"], "a": 2, "e": "這個民族是蒙古，統一中國後把人民分為四等。澶淵之盟是遼；成吉思汗建國時是南宋時期；帝國橫跨歐亞，沒有到非洲。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-128", "no": 128, "c": "c11", "src": "考卷 114上翰林社會2上B卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "范仲淹有「先天下之憂而憂，後天下之樂而樂」的志向，可看出宋代文人自我期許相當高，往往「以天下為己任」，所以他們通曉經典是為了學以致用，而這也是宋代理學最基本的精神。宋代的理學最主要融合了哪些思想？", "o": ["儒學、佛學", "儒學、伊斯蘭文化", "儒學、科學", "儒學、歐洲文化"], "a": 0, "e": "宋代理學主要是融合儒學與佛學。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-129", "no": 129, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "元代時，義大利人馬可波羅來到中國，他可能經歷下列何種狀況？", "o": ["在首都汴京街上看到國內外商人雲集", "欣賞《清明上河圖》所繪大部的形貌", "他屬於「色目人」等級，被朝廷重用", "逛市場要留意營業時間與地點的限制"], "a": 2, "e": "馬可波羅屬於色目人，受忽必烈重用。元代首都是大都不是汴京；《清明上河圖》畫的是北宋汴京；元代已沒有坊市限制。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-130", "no": 130, "c": "c5", "src": "考卷 114上翰林社會2上B卷 卷4 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "13 世紀時，義大利北部某教堂的神父告訴信徒，虔誠向上帝禱告並懺悔，便可驅過東方草原民族帶來的「黃禍」。上述中的「黃禍」，應該是指哪一個民族向歐洲的擴張？", "o": ["蒙古", "女真", "匈奴", "契丹"], "a": 0, "e": "13 世紀蒙古第二次西征打進歐洲，歐洲人稱為「黃禍」。", "rep": true, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-131", "no": 131, "c": "c5", "src": "考卷 114上翰林社會2上B卷 卷4 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷史課時，幾位同學探討有關忽必烈的重要事蹟，下列何人所言有誤？", "o": ["子韜：興兵滅南宋，統一全中國", "李晴：建國號為元，定都於大都", "郭錚：實施差別待遇的種族政策", "楊康：派使者前往西域通絡貿易"], "a": 3, "e": "忽必烈滅南宋、建國號元並定都大都、實施差別待遇。派使者去西域通絡貿易的是漢代張騫，不是忽必烈。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-132", "no": 132, "c": "c12", "src": "考卷 114上翰林社會2上B卷 卷4 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代由於人工磁化法（以磁石磨針鋒）的發明，使得指南針的應用範圍更廣。阿拉伯人將此技術傳入何處，開啟日後新航路的發現？", "o": ["美洲", "非洲", "澳洲", "歐洲"], "a": 3, "e": "阿拉伯人把指南針傳入歐洲，開啟後來新航路的發現。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-133", "no": 133, "c": "c13", "src": "考卷 114上翰林社會2上B卷 卷4 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "伊斯蘭教創立於 7 世紀，在宋元時期，向亞洲各地擴張，下列相關敘述何者錯誤？", "o": ["阿拉伯商人來華貿易，聚集地建立清真寺禮拜", "到中國貿易的穆斯林商人，乃地位最低下的南人", "因為暢通的海陸交通，使得穆斯林商人東來貿易", "伊斯蘭文化中的天文、曆法和醫學影響中國深遠"], "a": 1, "e": "穆斯林商人多屬色目人，地位僅次於蒙古人，不是地位最低的南人。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-134", "no": 134, "c": "c12", "src": "考卷 114上翰林社會2上B卷 卷4 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代是中國科學技術取得極大進展的時期，幾大發明的投入實用及大規模外傳均在此期，其中三項成就更是在航海、學術、戰爭方面有重大影響。上述所指是哪些成就？", "o": ["紙幣、造紙術、火藥", "羅盤、青銅器、火藥", "指南針、印刷術、火藥", "青銅器、造紙術、火藥"], "a": 2, "e": "宋代對航海、學術、戰爭影響最大的三項成就是指南針、印刷術、火藥。造紙術是東漢蔡倫改良的。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-135", "no": 135, "c": "c5", "src": "考卷 114上翰林社會2上B卷 卷4 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "正赫撰寫以蒙古為主題的報告，下列是其報告的部分內容，哪一項敘述有誤？", "o": ["鐵木真和繼位者發動三次西征", "蒙古西征之後建立了四大汗國", "蒙古對歐亞文化交流有重大貢獻", "成吉思汗建立元朝並定都大都"], "a": 3, "e": "建立元朝、定都大都的是忽必烈，不是成吉思汗。", "rep": true, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-136", "no": 136, "c": "c6", "src": "考卷 114上翰林社會2上B卷 卷4 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "「我的祖國被征服了，我淪為被統治者，但比起其他民族的遭遇，我們還算幸運，得到統治階層的信任，把我們當助手，派我們處理財政、稅賦方面的職務。」由上述判斷，拉伯最有可能是何種身分？", "o": ["西晉時，移入中原的匈奴人", "唐代時，居長安的突厥人", "金國統治中原時的契丹人", "元代統治中國時的西域人"], "a": 3, "e": "祖國被征服、卻受統治者信任、負責財政稅賦，是元代的色目人（西域人）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-137", "no": 137, "c": "c3", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "資料一：宋朝與「甲國」原在國土地的管轄有紛爭，長年戰鬥下，最後由宋朝皇帝親征後終於妥協。依照規定，宋朝交付甲國銀、絹，作為歲幣。訂定白溝河為邊界，且為維護兩國和平，宋朝為兄、甲國為弟。上文資料一的甲國，應為下列哪一民族？", "o": ["契丹", "匈奴", "女真", "蒙古"], "a": 0, "e": "皇帝親征後議和、給歲幣、以白溝河為界、宋為兄，是澶淵之盟，所以甲國是契丹（遼）。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-138", "no": 138, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (一) 2", "st": "考卷", "ctx": "", "fig": "", "q": "資料二：宋朝與「乙國」在戰爭下進入混亂，宋朝皇帝遭乙國擄走，危難之下宋室南遷，於臨安另立新部致力抗衡，雙方形成長期對峙的局面。關於資料二中的乙國，下列何者正確？", "o": ["當時的領袖為成吉思汗", "建國之後聯盟攻打甲國", "崛起地點位於今日西域", "最後滅亡於西夏的手上"], "a": 1, "e": "乙國擄走宋帝、宋室南遷，是金國（女真）。金建國後與北宋聯合攻打遼（甲國）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-139", "no": 139, "c": "c14", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (一) 3", "st": "考卷", "ctx": "資料一：宋朝與「甲國」原在國土地的管轄有紛爭，長年戰鬥下，最後由宋朝皇帝親征後終於妥協。依照規定，宋朝交付甲國銀、絹，作為歲幣。訂定白溝河為邊界，且為維護兩國和平，宋朝為兄、甲國為弟。\n資料二：宋朝與「乙國」在戰爭下進入混亂，宋朝皇帝遭乙國擄走，危難之下宋室南遷，於臨安另立新部致力抗衡，雙方形成長期對峙的局面。", "fig": "", "q": "根據資料中兩資料，當時的國際局勢呈現哪一特色？", "o": ["開始修築長城防禦外族", "北亞草原民族勢力強盛", "宋朝成為東亞秩序盟主", "四大汗國突破歐亞疆域"], "a": 1, "e": "契丹、女真先後強盛，都對宋朝造成威脅，可見北亞草原民族勢力強盛。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-140", "no": 140, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (一) 4", "st": "考卷", "ctx": "資料一：宋朝與「甲國」原在國土地的管轄有紛爭，長年戰鬥下，最後由宋朝皇帝親征後終於妥協。依照規定，宋朝交付甲國銀、絹，作為歲幣。訂定白溝河為邊界，且為維護兩國和平，宋朝為兄、甲國為弟。\n資料二：宋朝與「乙國」在戰爭下進入混亂，宋朝皇帝遭乙國擄走，危難之下宋室南遷，於臨安另立新部致力抗衡，雙方形成長期對峙的局面。", "fig": "", "q": "同學們針對文中兩份資料的內容進行討論，下列何者的說法正確？", "o": ["笑莉：資料一的背景應為永嘉之禍", "魯夫：資料二的背景應為澶淵之盟", "小桃：資料一當時親征的皇帝為趙匡胤", "小吉：資料二與乙國的紛爭為靖康之禍"], "a": 3, "e": "資料二是金擄走宋帝，就是靖康之禍。資料一是澶淵之盟，親征的皇帝是宋真宗。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-141", "no": 141, "c": "c3", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (二) 5", "st": "考卷", "ctx": "", "fig": "", "q": "故宮在 2020 年特別規畫「四方來朝—職貢圖特展」，展品中《契丹使朝聘圖》描繪在簽訂澶淵之盟後，契丹族前往朝廷拜見中國皇帝的場景。上文中提到的展品《契丹使朝聘圖》，可了解當時的國際局勢，畫中的契丹使節代表的是下列哪一政權？", "o": ["遼國", "金國", "西夏", "蒙古帝國"], "a": 0, "e": "契丹族建立的政權是遼國。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-142", "no": 142, "c": "c3", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (二) 6", "st": "考卷", "ctx": "故宮在 2020 年特別規畫「四方來朝—職貢圖特展」，展品中《契丹使朝聘圖》描繪在簽訂澶淵之盟後，契丹族前往朝廷拜見中國皇帝的場景。", "fig": "", "q": "文中畫作中接受契丹使節來朝聘的中國皇帝，是下列哪一位君王？", "o": ["漢武帝", "唐太宗", "宋真宗", "元世祖"], "a": 2, "e": "澶淵之盟是宋真宗時簽訂的。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-143", "no": 143, "c": "c1", "src": "考卷 114上翰林社會2上B卷 卷4 題組 (二) 7", "st": "考卷", "ctx": "故宮在 2020 年特別規畫「四方來朝—職貢圖特展」，展品中《契丹使朝聘圖》描繪在簽訂澶淵之盟後，契丹族前往朝廷拜見中國皇帝的場景。", "fig": "", "q": "文中使節被畫在邊緣處，但其國家強盛時，曾經是東亞國際局勢的主導者，鄰近多國都向其稱臣納貢，但最不可能包括下列何者？", "o": ["女真", "西夏", "高麗", "蒙古"], "a": 3, "e": "遼強盛時，女真、西夏、高麗都曾向遼稱臣；蒙古當時還沒形成強權，最不可能。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-144", "no": 144, "c": "c8", "src": "考卷 114上翰林社會2上B卷 卷6 第 17 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "會動的「清明上河圖」展覽，讓這幅描述北宋城市庶民生活反著名的畫作更生動有趣。此圖的展出使我們對北宋的社會經濟狀況有更深入的了解。我們可以在幅畫中看到下列何種現象？", "o": ["限制商業區的營業時間及地點", "小販在夜市裡叫賣玉米及番薯", "酒樓、茶館等商店四處並立著", "使用白銀與銅錢做為交易媒介"], "a": 2, "e": "《清明上河圖》可見酒樓、茶館等商店四處林立。玉米、番薯明代才傳入；宋代沒有限制營業時間地點；當時用銅錢、紙幣。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-145", "no": 145, "c": "c3", "src": "考卷 114上翰林社會2上B卷 卷6 第 18 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "圖(四)是宋代的國際關係示意圖，宋真宗年間所簽訂的澶淵之盟是由圖中哪兩個國家所簽訂？", "o": ["甲—北宋、乙—遼", "乙—北宋、丙—西夏", "甲—遼、丙—西夏", "甲—遼、乙—北宋"], "a": 3, "e": "澶淵之盟由北方的遼（甲）與北宋（乙）簽訂，雙方約為兄弟；丙是西夏。", "rep": false, "img": "q145", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-146", "no": 146, "c": "c12", "src": "考卷 114上翰林社會2上B卷 卷6 第 19 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "小平想以「中華文明對世界文化的貢獻」為題目寫一篇歷史小論文，下列為他在論文中所舉的例子，其中哪一個錯誤？", "o": ["造紙術", "《幾何原本》", "指南針", "活字印刷術"], "a": 1, "e": "《幾何原本》是西方數學著作，明代才傳入中國，不是中國對世界的貢獻。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-147", "no": 147, "c": "c11", "src": "考卷 114上翰林社會2上B卷 卷6 第 21 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "宋儒論學普遍提出「理」的觀念，說明宇宙萬物生成變化的根本就在「理」。關於此學術思想，下列敘述何者正確？", "o": ["「理學」將伊斯蘭文化融入儒學之中", "北宋學者朱熹集理學大成，完成「四書」", "宋代理學曾傳入朝鮮和日本，後發影響力", "元代以後科舉考試的定本是《回回藥方》"], "a": 2, "e": "宋代理學傳入朝鮮、日本，正確。理學融合的是佛學；朱熹是南宋人；科舉定本是《四書集注》。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-149", "no": 149, "c": "c5", "src": "考卷 114上翰林社會2上B卷 卷6 第 23 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "電視台要籌拍新劇「一代天驕成吉思汗」，下列資料何者最符合史實？", "o": ["鐵木真和繼位者發動三次西征", "成吉思汗建築元朝並定都大都", "創建橫跨歐亞非三洲的大帝國", "攻滅西夏、金、南宋統一天下"], "a": 0, "e": "鐵木真和繼位者發動三次西征，正確。建元、定都大都、滅南宋的是忽必烈；帝國沒有到非洲。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-150", "no": 150, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (一) 1（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "靖康之禍是宋代歷史上的浩劫，使北宋滅亡，宋室南遷，其影響面極廣。宋代詞人葉夢得作品《八聲甘州》中「坐看驕兵南渡，沸浪駭奔鯨」，描述靖康之禍外患南攻的情景。又或者「山外青山樓外樓，西湖歌舞幾時休？暖風熏得遊人醉，直把杭州作汴州。」根據文中內容判斷，詩中的「驕兵」是指哪一個政權？", "o": ["西夏", "遼", "金", "元"], "a": 2, "e": "靖康之禍時南攻的是金（女真）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-151", "no": 151, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (一) 2（跨課）", "st": "考卷", "ctx": "靖康之禍是宋代歷史上的浩劫，使北宋滅亡，宋室南遷，其影響面極廣。宋代詞人葉夢得作品《八聲甘州》中「坐看驕兵南渡，沸浪駭奔鯨」，描述靖康之禍外患南攻的情景。又或者「山外青山樓外樓，西湖歌舞幾時休？暖風熏得遊人醉，直把杭州作汴州。」", "fig": "", "q": "文中詩句提到的「杭州」是指南宋的首都，該首都為何？", "o": ["汴京", "南京", "長安", "臨安"], "a": 3, "e": "南宋的首都是臨安（今杭州）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-152", "no": 152, "c": "c4", "src": "考卷 114上翰林社會2上B卷 卷6 題組 (一) 3（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "南宋時以盡忠報國著稱、率軍抗金的英雄是下列何人？", "o": ["張騫", "岳飛", "朱熹", "鄭和"], "a": 1, "e": "南宋以盡忠報國著稱、率軍抗金的英雄是岳飛。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-153", "no": 153, "c": "c11", "src": "考卷 114上翰林社會2上C卷 卷4 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "熱悉中國文化的張老師以朱熹為研究對象，他打算在社區大學開設相關課程。下列哪一個主題適合邀請張老師做為講師？", "o": ["禮樂規範確認上下尊卑", "厲行法治限制思想自由", "《四書集注》與科舉考試", "主採用德行等評定士人"], "a": 2, "e": "朱熹著《四書集注》，元代起成為科舉考試定本，適合這個主題。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-154", "no": 154, "c": "c3", "src": "考卷 114上翰林社會2上C卷 卷4 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "「面對強國的入侵，大臣們莫不惶恐失措，有人建議直接投降，但是宰相卻敢建議皇帝御駕親征，先發制敵。」上述的皇帝應是指下列何人？", "o": ["宋太祖", "宋真宗", "鐵木真", "忽必烈"], "a": 1, "e": "宰相寇準建議宋真宗御駕親征，後來簽訂澶淵之盟。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-155", "no": 155, "c": "c10", "src": "考卷 114上翰林社會2上C卷 卷4 第 3 題", "st": "考卷", "ctx": "", "fig": "圖(一)市舶司管理外國商船入港、出海示意圖", "q": "唐宋時期國際貿易興盛，圖(一)為唐朝設置某機構的示意圖，該機構主要設置在港口周邊，負責管理各國商船進出及貿易商品徵稅事宜，這個機構名稱及主要對外港口應為何？", "o": ["驛站、臨安", "驛站、泉州", "市舶司、上海", "市舶司、廣州"], "a": 3, "e": "管理商船進出、徵稅的機構是市舶司，唐代設在廣州。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-156", "no": 156, "c": "c8", "src": "考卷 114上翰林社會2上C卷 卷4 第 4 題", "st": "考卷", "ctx": "", "fig": "圖(二)同學對白：包青天曾在此任府尹、《清明上河圖》呈現此城市風貌、北宋首都", "q": "圖(二)中同學們正在談論中國某個城市，依內容判斷，同學們說的應該是下列哪一個城市？", "o": ["北京", "長安", "洛陽", "汴京"], "a": 3, "e": "包青天任開封府尹、《清明上河圖》、北宋首都，都指汴京（今開封）。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-157", "no": 157, "c": "c5", "src": "考卷 114上翰林社會2上C卷 卷4 第 5 題", "st": "考卷", "ctx": "", "fig": "圖(三)對話框：他建立了蒙古帝國被推戴為成吉思汗、他發動西征遠達歐洲建立橫跨歐亞大帝國", "q": "圖(三)是同學對某歷史人物的討論，根據內容判斷，此人物應為何人？", "o": ["忽必烈", "鐵木真", "趙匡胤", "宋真宗"], "a": 1, "e": "建立蒙古帝國、被推為成吉思汗、發動西征的是鐵木真。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-158", "no": 158, "c": "c13", "src": "考卷 114上翰林社會2上C卷 卷4 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國自古以來從陸路引進許多西方文化，也間接影響了中國的科技、宗教等發展。若要了解元代時期的阿拉伯文化發展，應前往下列何處參觀？", "o": ["陝西兵馬俑", "泉州清淨寺", "燕雲十六州關城", "江西白鹿洞書院"], "a": 1, "e": "泉州清淨寺是阿拉伯風格的清真寺，可以了解伊斯蘭（阿拉伯）文化。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-159", "no": 159, "c": "c3", "src": "考卷 114上翰林社會2上C卷 卷4 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "澶淵之盟於 1004 年簽訂，主要是當時宋朝為了穩定北方邊疆，並解決與草原民族的長期對抗與衝突困境，所達成的協議，為中國歷史上一個重要的外交事件。上述的盟約為宋朝與哪一草原民族所簽訂？", "o": ["金", "遼", "蒙古", "西夏"], "a": 1, "e": "澶淵之盟是宋與遼（契丹）簽訂的。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-160", "no": 160, "c": "c3", "src": "考卷 114上翰林社會2上C卷 卷4 第 8 題", "st": "考卷", "ctx": "", "fig": "漫畫：遼國皇帝與宋真宗在澶州談判並簽訂盟約", "q": "圖(四)為其外族入侵中國的示意圖，此圖指的是下列哪一事件史實？", "o": ["澶淵之盟", "永嘉之禍", "蒙古西征", "靖康之禍"], "a": 0, "e": "宋真宗與遼在澶州簽訂盟約，就是澶淵之盟。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-161", "no": 161, "c": "c10", "src": "考卷 114上翰林社會2上C卷 卷4 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "蒙古帝國為了方便東西陸路貿易，曾出現由官方頒發的「牌符」，官員可利用此物，要求貿易路線上的交通站提供食宿及車馬。上述與何者的設立有關？", "o": ["郊商", "驛站", "洋行", "市舶司"], "a": 1, "e": "官員憑牌符可在驛站換馬、食宿，這與驛站的設立有關。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-162", "no": 162, "c": "c7", "src": "考卷 114上翰林社會2上C卷 卷4 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "古籍「早熟稻」的引進，使中國總體農業產量大幅提升，此品種應是在何時引進中國？", "o": ["漢代", "宋代", "唐代", "元代"], "a": 1, "e": "早熟稻是在宋代引進中國的。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-163", "no": 163, "c": "c4", "src": "考卷 114上翰林社會2上C卷 卷4 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷史是以古鑑今，但卻常重複覆轍。以宋朝為例，北宋聯合外族消滅敵人後，卻被聯合的外族所滅，後來的南宋亦是如此。北宋和南宋各為哪一外族所滅？", "o": ["匈奴、突厥", "匈奴、金", "遼、蒙古", "金、蒙古"], "a": 3, "e": "北宋聯金滅遼後被金所滅；南宋聯蒙滅金後被蒙古所滅。", "rep": true, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-164", "no": 164, "c": "c6", "src": "考卷 114上翰林社會2上C卷 卷4 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "蒙古人是在中國歷史上建立政權的草原民族之一，但為了維持蒙古人尊貴地位而實施差別待遇的種族政策，讓廣大的漢人受到不平等待遇，民變四起。上述民族所建立的政權應為圖(五)中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "960 年宋朝建立、1368 年明朝建立。宋之前的甲是五代十國，乙、丙是與北宋、南宋並立的遼和金，丁在南宋之後、明之前，就是蒙古人建立的元朝。", "rep": false, "img": "", "fh": "<div class=\"tline\"><div class=\"tl-row\"><div class=\"tl-c\">隋</div><div class=\"tl-c\">唐</div><div class=\"tl-c tl-k\">甲</div><div class=\"tl-song\"><div class=\"tl-top\">宋</div><div class=\"tl-mid\"><span>北宋</span><span>南宋</span></div><div class=\"tl-bot\"><span class=\"tl-k\">乙</span><span class=\"tl-k\">丙</span></div></div><div class=\"tl-c tl-k\">丁</div><div class=\"tl-c\">明</div><div class=\"tl-c tl-end\">清</div></div><div class=\"tl-axis\"><span style=\"left:30%\">▼ 960 年</span><span style=\"left:63%\">▼ 1368 年</span></div><div class=\"tl-cap\">圖(五)（依原卷重畫）</div></div>", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-165", "no": 165, "c": "c11", "src": "考卷 114上翰林社會2上C卷 卷4 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代某一學術思想是儒學在此時的理論高峰，由南宋學者集其大成，不僅對當時的學術界和政治體制起到了引領作用，也對中國後來的思想文化等產生影響，此一思想體系在日後也傳至朝鮮與日本，頗受重視。上述的學術思想是指何者？", "o": ["回學", "史學", "法學", "理學"], "a": 3, "e": "南宋集大成、後來傳到朝鮮和日本的學術思想是理學。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-166", "no": 166, "c": "c11", "src": "考卷 114上翰林社會2上C卷 卷4 第 14 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋代理學即為兩宋至明代的儒學，此時期雖以儒學內容為主，同時也融合了下列何種思想？", "o": ["佛學思想", "法治思想", "封建思想", "集權思想"], "a": 0, "e": "理學以儒學為主，同時融合了佛學思想。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-167", "no": 167, "c": "c12", "src": "考卷 114上翰林社會2上C卷 卷4 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "徐競可能是中國最早將指南針用於航海的人，他奉使赴高麗時曾說：「夜在洋中不可住，維觀星斗前邁。若晦冥，則用指南浮針，以辨南北。」徐競應該是哪一個時代的人？", "o": ["唐代", "隋代", "宋代", "漢代"], "a": 2, "e": "宋代已經把指南針用在航海上，徐兢是北宋人。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-168", "no": 168, "c": "c11", "src": "考卷 114上翰林社會2上C卷 卷4 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "圖(六)是《漫畫中國史》中描繪某時期的社會狀況。由漫畫內容判斷，這應是哪一朝代的情形？", "o": ["唐代", "漢代", "宋代", "元代"], "a": 3, "e": "熟讀《四書集注》以求取功名，是元代以後的科舉，選項中只有元代符合。", "rep": false, "img": "q168", "fh": "", "maps": [], "chk": "選項 (C)"}, {"id": "h3-169", "no": 169, "c": "c10", "src": "考卷 114上翰林社會2上C卷 卷4 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "如果你是生活於北宋時期，不可能有下列何種生活體驗？", "o": ["晚上可以去逛夜市", "閱讀採活字版印刷的書籍", "在市舶司檢查入港的貨物", "看到前往驛站的駱駝商隊，絡繹不絕"], "a": 3, "e": "驛站廣設、駱駝商隊絡繹不絕是元代的景象。夜市、活字印刷書、市舶司在北宋都有。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-170", "no": 170, "c": "c4", "src": "考卷 114上翰林社會2上C卷 卷4 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "北宋在某次聯合外族夾擊遼國時，外族發現了北宋皇室的軟弱與腐敗，因此隔年趁北宋仍為收復失土而普天同慶時，攻進汴京，造成皇室被俘，剩餘的皇子則在南方建立新政權。上述外族應為何者？", "o": ["女真", "蒙古", "西夏", "鮮卑"], "a": 0, "e": "與北宋聯合夾擊遼國、隨後攻陷汴京俘虜皇室的是女真（金）。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-171", "no": 171, "c": "c4", "src": "考卷 114上翰林社會2上C卷 卷4 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "岳飛在《滿江紅》中提到：「靖康恥，猶未雪。臣子恨，何時滅！」文中所說的「臣子恨」，是指哪一朝代遭外族入侵而滅亡？", "o": ["隋代", "唐代", "北宋", "南宋"], "a": 2, "e": "「靖康恥」指北宋被金所滅，所以「臣子恨」是北宋滅亡。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-172", "no": 172, "c": "c5", "src": "考卷 114上翰林社會2上C卷 卷4 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "下表是老師上課時講解的重點，根據內容判斷，老師講解的主題是下列何者？[首都：大都（今北京）；對外戰爭：滅西夏、金、南宋；滅亡原因：帝位繼承紛爭不斷、民變紛起]", "o": ["秦漢帝國興衰發展", "大唐的創立與衰徹", "宋朝政經發展概述", "元朝帝國的興衰史"], "a": 3, "e": "首都大都、滅西夏金南宋、帝位紛爭與民變，是元朝的興衰史。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-173", "no": 173, "c": "c12", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 1", "st": "考卷", "ctx": "", "fig": "", "q": "阿拉伯人自唐朝以來與中國互動密切，也是促進東西文化交流的重要推手，下列何者的向外傳播與阿拉伯人較不相關？", "o": ["火藥", "造紙術", "指南針", "伊斯蘭教"], "a": 0, "e": "造紙術（怛羅斯之役）、指南針、伊斯蘭教的傳播都和阿拉伯人有關；火藥主要是經蒙古西征西傳。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-174", "no": 174, "c": "c4", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 2", "st": "考卷", "ctx": "", "fig": "", "q": "年假時，阿明帶著妻小至杭州旅遊，他們參觀紀念岳飛忠勇與部隊的岳王廟。阿明說道：「當時岳飛馳騁沙場，敵人見其軍旗，聞風喪膽，真是威風凜凜呀。」阿明所指的敵人應為何者？", "o": ["契丹", "女真", "匈奴", "蒙古"], "a": 1, "e": "岳飛抗金，敵人是女真。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-175", "no": 175, "c": "c1", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 3", "st": "考卷", "ctx": "", "fig": "", "q": "北京市五大水系之一的大清河，有一條支流名為拒馬河，這條河川流經了紫荊關長城，是華北平原進入太行山的重要隘口。該河舊名為白溝河，在歷史上它是燕雲十六州內界河，用以防禦中原不受北方草原民族入侵。上述區域在 10 世紀初時被哪一外族占據？", "o": ["女真", "匈奴", "契丹", "蒙古"], "a": 2, "e": "燕雲十六州在 10 世紀初被契丹占據。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-176", "no": 176, "c": "c3", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 4", "st": "考卷", "ctx": "", "fig": "圖(七)節錄澶淵之盟內容：歲幣絹20萬匹、銀10萬兩，雙方以白溝河為界，約為兄弟之邦", "q": "圖(七)是某外族與宋朝簽訂的盟約。由內容判斷，此盟約的簽訂對宋朝帶來下列何種影響？", "o": ["宋朝建立東亞可汗體系", "後來引發此外族攻陷首都", "宋朝就此免除外患的威脅", "與外族維持一百多年和平"], "a": 3, "e": "澶淵之盟後，宋遼維持一百多年和平。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-177", "no": 177, "c": "c8", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 5", "st": "考卷", "ctx": "", "fig": "", "q": "電視臺播放的穿越時空劇，如果穿越至北宋時期，可能會看到下列哪些事情？", "o": ["蒙古人為維持統治實施種族政策", "夜晚的街上有許多酒樓仍在營業", "使用寶鈔作為國際貿易交易媒介", "各地設驛站使東西貿易海陸繁盛"], "a": 1, "e": "北宋夜晚街上有酒樓營業（夜市興盛）。種族政策、寶鈔、廣設驛站都是元代的事。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-178", "no": 178, "c": "c6", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 6", "st": "考卷", "ctx": "", "fig": "圖(八)元代種族階級圖：第一階甲、第二階乙、第三階丙、第四階丁", "q": "馬可波羅是一名義大利商人，曾在元朝時從泉州進入中國貿易，把在中國所看到的景象寫成《東方見聞錄》。依照圖(八)中元朝的種族政策，他的階級應該屬於圖中何者？", "o": ["甲", "乙", "丙", "丁"], "a": 1, "e": "馬可波羅屬於色目人，是第二等，就是乙。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-179", "no": 179, "c": "c6", "src": "考卷 114上翰林社會2上C卷 卷4 進階思考題 7", "st": "考卷", "ctx": "", "fig": "", "q": "根據下列史料內容判斷，這應為何者所實施的政策？[(一)科舉考試方面：蒙古人、色目人列右榜，漢人、南人列左榜... (二)政治方面：中央到地方的重要官員，正職由蒙古人與少數色目人擔任...]", "o": ["漢代", "唐代", "元代", "宋代"], "a": 2, "e": "蒙古人、色目人列右榜，漢人、南人列左榜，重要官職由蒙古人擔任，是元代的差別待遇。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-180", "no": 180, "c": "c2", "src": "考卷 114上翰林社會2上C卷 卷4 題組 (一) 1", "st": "考卷", "ctx": "", "fig": "", "q": "宋元時期，漢人政權受到外族威脅，雖紛擾不斷，卻也促成促進民族融合的一面；此外，庶民（平民）文化與學術思想亦是蓬勃發展，使中國文明特色更加多元。上文中提及的漢人政權，自身軍事實力難以應付外族威脅，是由於此政權所實施的哪一政策所致？", "o": ["偏重文人政治", "重用胡人武將", "採平等開放的外族政策", "展開西征過度濫用民力"], "a": 0, "e": "宋代偏重文人政治、重文輕武，所以軍事實力難以應付外患。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-182", "no": 182, "c": "c8", "src": "考卷 114上翰林社會2上C卷 卷4 題組 (二) 3", "st": "考卷", "ctx": "", "fig": "", "q": "中國大約在 10 世紀時已有發明煙火的記載，主要用於盛大的節慶中。根據記載宋代的元宵節不僅有看花燈、猜燈謎、吃湯圓等活動，還會放煙火，在夜半時分街頭熱鬧非凡，燈籠懸掛在街道兩旁，人們摩肩接踵逛市集。上文中夜市的出現，主要是由於不再受到哪一制度的限制？", "o": ["郡縣制度", "封建禮樂", "坊市制度", "地方割據"], "a": 2, "e": "夜市能出現，是因為不再受到坊市制度的限制。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-183", "no": 183, "c": "c12", "src": "考卷 114上翰林社會2上C卷 卷4 題組 (二) 4", "st": "考卷", "ctx": "中國大約在 10 世紀時已有發明煙火的記載，主要用於盛大的節慶中。根據記載宋代的元宵節不僅有看花燈、猜燈謎、吃湯圓等活動，還會放煙火，在夜半時分街頭熱鬧非凡，燈籠懸掛在街道兩旁，人們摩肩接踵逛市集。上文中夜市的出現，主要是由於不再受到哪一制度的限制？", "fig": "", "q": "承上題，上文中的火藥兵器，在哪一場戰爭中被改良而西傳？", "o": ["永嘉之禍", "蒙古西征", "靖康之禍", "怛羅斯之役"], "a": 1, "e": "火藥兵器在蒙古西征時被改良並傳到西方。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-184", "no": 184, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 1 題", "st": "考卷", "ctx": "", "fig": "", "q": "關於元朝的開國君主元世祖，下列敘述何者正確？", "o": ["曾經發動西征", "此人為鐵木真", "被尊稱為成吉思汗", "此人為忽必烈"], "a": 3, "e": "元世祖就是忽必烈。發動西征、被尊為成吉思汗的是鐵木真。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-185", "no": 185, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 2 題", "st": "考卷", "ctx": "", "fig": "", "q": "俄羅斯是世界最強大的戰鬥力之一，被稱為戰鬥民族，領導人普丁在國際局勢上，經常主導各項的工作，其動向與國勢皆備受關注。但是，一名研究中國史的歷史學家表示：「中國蒙古騎兵曾經將俄羅斯土地收歸大蒙古國的版圖。」這應該是蒙古四大汗國中的哪一個？", "o": ["伊兒汗國", "欽察汗國", "窩闊台汗國", "察合台汗國"], "a": 1, "e": "欽察汗國位在今天的俄羅斯一帶。", "rep": true, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-186", "no": 186, "c": "c13", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 3 題", "st": "考卷", "ctx": "", "fig": "", "q": "有阿拉伯風格的「清淨寺」，初建於西元 11 世紀初。關於該寺的敘述，下列何者正確？", "o": ["該寺初建於廣州", "該寺屬於佛教建築", "該寺最早建立於南宋時期", "該寺出現與來華經商的穆斯林有關"], "a": 3, "e": "清淨寺建於北宋時的泉州，與來華經商的穆斯林有關。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-187", "no": 187, "c": "c12", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 4 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋元之際除了國內外商貿發展興盛外，在科技方面亦有突出表現。但下列哪一項發明，與此時期對中西方科技發展的貢獻無關？", "o": ["造紙術", "火藥兵器技術", "指南針", "印刷術"], "a": 0, "e": "造紙術是東漢蔡倫改良、唐代西傳，不屬於宋元時期的科技貢獻。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-188", "no": 188, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 5 題", "st": "考卷", "ctx": "", "fig": "", "q": "哲甫看到一則新聞：「中國古都口，承襲了華夏文明延續的清晰血脈，保留著最多華夏子孫獨特的文化記憶，尤其是此地一幅《清明上河圖》（如上圖），更是生動彩顯了口繁華、熱鬧景象，以及優美的自然風光。」上述口中應填入下列哪一個城市？", "o": ["北京", "南京", "長安", "開封"], "a": 3, "e": "《清明上河圖》畫的是北宋首都汴京，也就是今天的開封。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-189", "no": 189, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 6 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列詩句出自於林升的《題臨安邸》，其主要是在諷刺下列哪一政權偏安江南的情形？[詩句：山外青山樓外樓，西湖歌舞幾時休，暖風熏得遊人醉，直把杭州作汴州。]", "o": ["東晉", "北宋", "南宋", "元代"], "a": 2, "e": "「直把杭州作汴州」諷刺南宋偏安臨安，忘了收復汴京。", "rep": true, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-190", "no": 190, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 7 題", "st": "考卷", "ctx": "", "fig": "", "q": "夜市中各類特色小吃可以說是臺灣最獨特的飲食文化。中國古代的哪一個朝代打破以往坊（住宅區）、市（商業區）分離的限制，使得夜市得以興盛發展？", "o": ["周朝", "漢朝", "唐朝", "宋朝"], "a": 3, "e": "宋朝打破坊、市分離的限制，夜市因此興盛。", "rep": false, "img": "", "fh": "", "maps": [], "chk": "選項 (C)"}, {"id": "h3-191", "no": 191, "c": "c1", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 8 題", "st": "考卷", "ctx": "", "fig": "", "q": "契丹族在 10 世紀初建立政權，並巧取豪奪中原某一軍事要地，對後來中國新興的朝代造成威脅。上述軍事要地是指下列哪一地區？", "o": ["西夏", "燕雲十六州", "吐蕃", "大理"], "a": 1, "e": "契丹取得的中原軍事要地是燕雲十六州。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-192", "no": 192, "c": "c7", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 9 題", "st": "考卷", "ctx": "", "fig": "", "q": "農業專家在中國歷史紀錄上發現，農業生產的興衰往往和國家、民族的興衰相互結合。在他所發現的一則資料上提到了北宋人口的增加是因為自「其他地方」引入了「某樣作物」，影響了糧食的生產。文中的「地方」與「作物」分別所指為何？", "o": ["越南—早熟稻", "中南美洲—玉米", "歐洲—馬鈴薯", "西班牙—蕃薯"], "a": 0, "e": "北宋從越南（占城）引進早熟稻，糧食增產、人口增加。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-193", "no": 193, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 10 題", "st": "考卷", "ctx": "", "fig": "", "q": "「在元代，統治者由於自知財務相關的事宜並非本族族人所擅長，因此將國家經濟大權的管理，委託給某一個善於經營商貿行為的特定族群來操作。」下列哪一個族群，最有可能是受到元朝在財政方面委以重用？", "o": ["色目人", "女真人", "契丹人", "漢人"], "a": 0, "e": "色目人善於理財經商，受元朝在財政方面重用。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-194", "no": 194, "c": "c14", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 11 題", "st": "考卷", "ctx": "", "fig": "", "q": "中國宋元之際，在東亞大陸上呈現多民族政權並立的局勢，右列各民族及其建立政權的配對，何者錯誤？[民族/政權：甲、契丹族/西夏；乙、漢族/宋朝；丙、女真族/金國；丁、蒙古族/元朝]", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "契丹族建立的是遼，西夏是党項族建立的，所以甲錯誤。", "rep": false, "img": "", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-195", "no": 195, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 12 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是元朝一項重要的政治制度，有關該制度的解讀，下列說法何者需要修正？", "o": ["蒙古至上", "漢人地位最低", "種族差別待遇", "南人沒有地位"], "a": 1, "e": "元代地位最低的是南人，不是漢人，所以「漢人地位最低」需要修正。", "rep": false, "img": "q195", "fh": "", "maps": [], "chk": "選項 (B)"}, {"id": "h3-196", "no": 196, "c": "c13", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 13 題", "st": "考卷", "ctx": "", "fig": "", "q": "宋元時期貿易發達，文化交流亦繁盛。伊斯蘭教的傳播對中國的影響並不包括下列何者？", "o": ["天文曆法", "宗教文化", "醫學藥方", "活字印刷術"], "a": 3, "e": "活字印刷術是北宋畢昇發明的，不是伊斯蘭文化帶來的影響。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-197", "no": 197, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 14 題", "st": "考卷", "ctx": "", "fig": "右圖：13 世紀歐洲民眾在神父帶領下祈禱，躲避一支來自東方、攜帶威力強大火砲的騎兵。", "q": "右圖是 13 世紀歐洲民眾對於來自東方的某一部原民族挾帶著威力強大的火砲，四處攻城掠地，在義大利神父帶領下祈求平安的情景。關於上述場景，應該與下列哪一民族有關？", "o": ["鮮卑人", "匈奴人", "契丹人", "蒙古人"], "a": 3, "e": "13 世紀帶著火砲西征、威脅歐洲的是蒙古人。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-198", "no": 198, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 15 題", "st": "考卷", "ctx": "", "fig": "", "q": "「靖康恥，猶未雪。臣子恨，何時滅！駕長車，踏破賀蘭山缺。壯志飢餐胡虜肉，笑談渴飲匈奴血。待從頭、收拾舊山河，朝天闕。」上述是岳飛所寫「滿江紅」，岳飛應是下列哪一時期的名將？", "o": ["北宋初期", "南宋初期", "南宋末期", "元代初期"], "a": 1, "e": "岳飛是南宋初期的抗金名將。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-199", "no": 199, "c": "c10", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 16 題", "st": "考卷", "ctx": "", "fig": "", "q": "關於宋元時期在社會經濟上呈現的特色，下列敘述何者與實際情形一致？", "o": ["維持嚴格的坊市分離", "有外國人大量在中國經商", "僅在廣州一地設立市舶司", "宋元時期因為受戰爭頻繁，國內外商業衰退"], "a": 1, "e": "宋元時期有大量外國人在中國經商。宋代坊市已經瓦解；市舶司不只設在廣州；宋元商業很興盛。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-200", "no": 200, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 17 題", "st": "考卷", "ctx": "", "fig": "", "q": "《清明上河圖》在故宮展出，秉崴買了一幅仿製品回家欣賞，並發現其中許多有趣的文化特色。根據當時朝代來判斷，秉崴最不可能在畫中發現到什麼？", "o": ["當鋪", "酒樓", "香料鋪", "坊市分離"], "a": 3, "e": "宋代坊市制度已經瓦解，畫中不會出現坊市分離。", "rep": false, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-201", "no": 201, "c": "c11", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 18 題", "st": "考卷", "ctx": "", "fig": "", "q": "小敏為了準備期末報告，到圖書館借閱了右圖資料。關於宋元時期學術的發展，下列敘述何者錯誤？[資料封面書影：《四書集注》]", "o": ["宋朝提倡儒學，儒家學者融合佛學等思想，形成「理學」", "南宋朱熹是理學的大成，曾於白鹿洞書院講學", "《四書集注》於宋代時成為科舉考試的定本", "宋代理學對朝鮮和日本影響深遠"], "a": 2, "e": "《四書集注》是元代才成為科舉考試定本，不是宋代。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-202", "no": 202, "c": "c3", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 19 題", "st": "考卷", "ctx": "", "fig": "", "q": "右列是中國某朝代對外簽署某項和約的內容，經過仔細精算，發現歲幣支出只占財政 1%，故以歲幣換取雙方一百多年的和平是值得的。有關此和約的敘述，下列何者正確？[條約內容：1.雙方約為兄弟之邦 2.雙方劃定疆界 3.每年給予歲幣]", "o": ["是南宋", "是女真族", "和約簽訂在宋太祖時", "此為「澶淵之盟」的內容"], "a": 3, "e": "約為兄弟之邦、劃定疆界、每年給歲幣，是北宋與遼的澶淵之盟。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-203", "no": 203, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 20 題", "st": "考卷", "ctx": "", "fig": "", "q": "麗均看到一則新聞報導：「農曆 2 月 1 日是岳飛生日，日月潭文武廟每年此刻都會舉辦岳武穆王誕辰祈安法會，表彰忠孝、番弛禮儀；岳飛的第 28 代孫岳朝軍特地率團參拜祭祖，互訪交流。」在歷史上的岳飛曾有下列何項作為，成為後世的忠義表率？", "o": ["抗力金國收復國土", "主張給歲幣和平", "主張對金屈服稱貢", "主張聯合蒙古滅金"], "a": 0, "e": "岳飛抵抗金國、力圖收復國土，成為後世的忠義表率。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-204", "no": 204, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 21 題", "st": "考卷", "ctx": "", "fig": "", "q": "奇美實業創辦人許文龍說：「最近我很多日本朋友都在問我，這位企業家是什麼來歷，為何能在如此短的時間內征服全球市場，我認為他就像現代的成吉思汗……」承瑩看到上述新聞後，上網查詢有關「成吉思汗」這位歷史人物的生平，他會看到下列哪一項事蹟？", "o": ["首位以草原民族身分，入主中原的君主忽必烈", "結束東亞多民族政權並立局面的君主", "使蒙古人成為第一個統治整個中國的草原民族", "鐵木真和繼位者藉由三次軍事行動，建立橫跨歐亞大陸的大帝國"], "a": 3, "e": "鐵木真和繼位者發動三次西征，建立橫跨歐亞的大帝國。入主中原、統一中國的是忽必烈。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-205", "no": 205, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 22 題", "st": "考卷", "ctx": "", "fig": "", "q": "西元 13 世紀時，有位歐洲人馬可波羅口述自己在東方的經歷與見聞：「我隨著叔父來到富庶的東方國家，被稱為『色目人』(甲)，受到元世祖『鐵木真』(乙)重用。當年我來到此國首都『南京』(丙)之後，開始了驚奇之旅。我也發現此國的首都築有通往各地的道路，每隔一段距離就要署名為『驛站』(丁)的招待所，提供政府官員和過往商旅使用，非常便利。」上述『引號』內容何者正確？", "o": ["甲乙", "乙丙", "丙丁", "甲丁"], "a": 3, "e": "馬可波羅屬色目人（甲對）、驛站（丁對）；元世祖是忽必烈，首都是大都。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-206", "no": 206, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 23 題", "st": "考卷", "ctx": "", "fig": "", "q": "元朝時期實施差別待遇的民族政策，依序將統治的居民分為「蒙古人、色目人、漢人、南人」四個階級，有關於四個階級的敘述，下列何者正確？", "o": ["蒙古人的地位最高", "漢人包括原本南宋統治的漢人及南方各族群", "色目人擅長理財，由女真人、契丹人來擔任", "在政治、科舉考試方面，四個階級公平競爭"], "a": 0, "e": "蒙古人地位最高，正確。原南宋統治的是南人；色目人是西域各族；四個階級並不公平。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-207", "no": 207, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 24 題", "st": "考卷", "ctx": "", "fig": "", "q": "史學家黃仁宇曾說：「從物質生活講，十二世紀的中國，無疑的已領先世界。」關於上述史學家的論述，主要是針對宋代哪一項特色而提出的看法？", "o": ["胡漢融合的多元文化", "科技發達與商業興盛", "統一幣制並通行全國", "開通絲路使商品交流"], "a": 1, "e": "宋代科技發達、商業興盛，所以物質生活領先世界。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-208", "no": 208, "c": "c3", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 第 25 題", "st": "考卷", "ctx": "", "fig": "", "q": "歷史老師在黑板上貼上一幅漫畫，請解北宋與某一外族所簽訂的「澶淵之盟」。漫畫中的胡人代表，指的是圖中哪一個國家？", "o": ["甲", "乙", "丙", "丁"], "a": 3, "e": "澶淵之盟是北宋與遼簽訂的，遼在北宋的北方，圖中是丁。", "rep": false, "img": "q208", "fh": "", "maps": ["map-nsong"], "chk": ""}, {"id": "h3-209", "no": 209, "c": "c10", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 題組 (一) 26", "st": "考卷", "ctx": "", "fig": "", "q": "泉州市舶司，位於今福建省泉州市鯉城區。「市舶司」是中國在各海港設立的對外貿易管理機構，相當於現在的海關。今日泉州、明州、杭州的市舶司遺址俱已湮沒，而泉州市舶司遺址是唯一保存下來的古海關遺址。宋元時期海上貿易鼎盛，不少因經商貿易來到中國的穆斯林商人，他們常至「聖友之寺」（清真寺）進行祈禱。上文中市舶司最早建立於下列哪一朝代？", "o": ["秦朝", "漢朝", "唐朝", "宋朝"], "a": 2, "e": "市舶司最早在唐代設立（廣州），宋元時期最興盛。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-210", "no": 210, "c": "c13", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 題組 (一) 27", "st": "考卷", "ctx": "泉州市舶司，位於今福建省泉州市鯉城區。「市舶司」是中國在各海港設立的對外貿易管理機構，相當於現在的海關。今日泉州、明州、杭州的市舶司遺址俱已湮沒，而泉州市舶司遺址是唯一保存下來的古海關遺址。宋元時期海上貿易鼎盛，不少因經商貿易來到中國的穆斯林商人，他們常至「聖友之寺」（清真寺）進行祈禱。上文中市舶司最早建立於下列哪一朝代？", "fig": "", "q": "承上文，上述經商貿易來到中國的穆斯林商人信仰的最可能是下列哪一宗教？", "o": ["基督教", "天主教", "伊斯蘭教", "佛教"], "a": 2, "e": "穆斯林信仰的是伊斯蘭教。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-211", "no": 211, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 題組 (二) 28", "st": "考卷", "ctx": "", "fig": "", "q": "下列為中國歷史上某時期的演變過程——圖(一)中「甲」最終亡於下列哪一民族之手？", "o": ["匈奴", "鮮卑", "契丹", "女真"], "a": 3, "e": "圖一的北宋（甲）亡於女真（金）。", "rep": false, "img": "q211", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-212", "no": 212, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 題組 (二) 29", "st": "考卷", "ctx": "", "fig": "", "q": "關於由圖(一)轉變至圖(二)，最可能與下列哪一事件有關？", "o": ["張騫出使西域", "澶淵之盟", "靖康之禍", "蒙古西征"], "a": 2, "e": "北宋變成南宋的關鍵是靖康之禍。", "rep": false, "img": "q211", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-213", "no": 213, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第4次練習 題組 (二) 30", "st": "考卷", "ctx": "", "fig": "", "q": "圖(二)中的乙最終亡於下列哪一民族之手？", "o": ["蒙古", "鮮卑", "契丹", "女真"], "a": 0, "e": "南宋（乙）最後亡於蒙古。", "rep": false, "img": "q211", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-214", "no": 214, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 1 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "蒙古族曾建立龐大的帝國，領土包括中國的元朝。但是對於不同民族的治理，卻因為了維持本族地位而採取了「差別待遇」。依此推論，下列哪一種族群的種族地位「最低」？", "o": ["蒙古人", "色目人", "南人", "漢人"], "a": 2, "e": "元代四等人中，南人地位最低。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-215", "no": 215, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 3 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "宋代庶民文化興起，各種文藝活動應運而生，此時如果在北宋的街道上，最有可能遇到下列哪一情形？", "o": ["在正店品嘗美味的蕃薯料理", "在夜市中用白銀購買烤玉米", "在茶館裡與友人討論《幾何原本》", "在市集的香料鋪上購買來自東南亞的香料"], "a": 3, "e": "宋代海外貿易發達，可以買到東南亞的香料。番薯、玉米明代才傳入；白銀不是宋代主要貨幣；《幾何原本》明代才傳入。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-216", "no": 216, "c": "c11", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 4 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "右列四本書是儒家經典，其經由下列何人做註解，而成元朝時科舉考試的定本？[圖示書籍：《論語》《孟子》《大學》《中庸》]", "o": ["朱熹", "張擇端", "畢昇", "朱元璋"], "a": 0, "e": "朱熹替四書作注，成為《四書集注》，元代起是科舉定本。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-217", "no": 217, "c": "c3", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 5 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "有一個朝代的基本國策是重文輕武，下自臣民，上至君王均提倡讀書的重要。其中有一位皇帝在外敵入侵時曾聽從宰相建議御駕親征，還曾寫下《勸學詩》與大家努力讀書，爭取美好的未來，亦留下「書中自有黃金屋，書中有女顏如玉」的千古名句。此位皇帝是下列何者？", "o": ["唐太宗", "宋真宗", "元世祖", "明成祖"], "a": 1, "e": "重文輕武、聽從宰相寇準建議御駕親征、寫《勸學詩》的是宋真宗。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-218", "no": 218, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 6 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "某宋代畫家自述：「我擅長繪畫，把那麼繁榮富庶的首都中各各式各樣的建築細膩且生動的描繪出來，例如人潮不斷的熱鬧街道和各種知名正店、客棧、當鋪等店家，甚至連橋上的行人與河上船家都有清楚地描繪出來。」關於這位畫家，下列敘述何者錯誤？", "o": ["他是張擇端", "畫作大約完成於北宋年間", "此幅作品名為「清明上河圖」", "畫作中所描繪的繁華之都指臨安"], "a": 3, "e": "《清明上河圖》描繪的是北宋汴京，不是臨安。", "rep": true, "img": "", "fh": "", "maps": ["qingming"], "chk": ""}, {"id": "h3-219", "no": 219, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 7 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "右表為元朝某時期的考題以及科舉考試的錄取名額。表中資料可知，元朝對不同種族實施下列何種政策？[表格：總錄取人數 蒙古人75人、色目人75人、漢人75人、南人75人，但南人人口數約5,800萬人，蒙古人僅約40萬戶]", "o": ["推行漢化政策", "蒙漢嚴格分界", "文字獄及秘密監控", "實施民族差別待遇政策"], "a": 3, "e": "各族人口差距很大，錄取名額卻一樣，是民族差別待遇政策。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-220", "no": 220, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 8 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "考古學家近年積極尋找一位蒙古英雄的陵墓，他在 13 世紀初統一部落，建立帝國，並發動第一次西征。上述這位英雄是指何人？", "o": ["柳成幼", "忽必烈", "鐵木真", "窩闊台"], "a": 2, "e": "13 世紀初統一部落、建立帝國、發動第一次西征的是鐵木真（成吉思汗）。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": "選項 (D)"}, {"id": "h3-221", "no": 221, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 9 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "「住商合一」是臺灣普遍的現象，平常白天樓下開店作生意，晚上關店後樓上就作為全家休憩的場所。在中國歷史上，下列哪一個朝代也可以看到這種住商合一、商業蓬勃的情景？", "o": ["周代", "漢代", "唐代", "宋代"], "a": 3, "e": "宋代坊市制度瓦解，出現住商合一、商業蓬勃的景象。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-222", "no": 222, "c": "c6", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 11 題（跨課）", "st": "考卷", "ctx": "", "fig": "右圖：元代社會階級金字塔，由上而下依序為甲、乙、丙、丁四層。", "q": "朮赤是元朝時的蒙古人，在元朝統治下的中國社會中，他的種族地位應位於右圖中哪一個階層？", "o": ["甲", "乙", "丙", "丁"], "a": 0, "e": "蒙古人地位最高，在金字塔最上層，就是甲。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-223", "no": 223, "c": "c7", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 12 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "中國歷史上，由於糧食作物的引進，養活了眾多的人，使得人口得以成長。有關「早熟稻、番薯」，其分別於何時引進中國？", "o": ["明；清", "宋；元", "元；明", "宋；明"], "a": 3, "e": "早熟稻在宋代引進，番薯在明代引進。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-224", "no": 224, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 14 題（跨課）", "st": "考卷", "ctx": "", "fig": "圖(一)北宋對外形勢圖演變為圖(二)南宋對外形勢圖", "q": "下列分別是北宋與南宋的對外關係圖。由圖(一)演變成圖(二)的關鍵史事為何？", "o": ["澶淵之盟", "怛羅斯之役", "靖康之禍", "蒙古西征"], "a": 2, "e": "北宋變成南宋的關鍵是靖康之禍。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-225", "no": 225, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 17 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "南宋末年，文天祥被擄至元朝大都，在獄中作〈正氣歌〉以明其志，皇帝對其志氣才學讚賞有加，無奈他仍難逃被處死的命運。下列敘述何者正確？", "o": ["文天祥被擄前，西夏與金國已被蒙古所滅", "當時的元朝皇帝是鐵木真", "南宋被滅是因為靖康之禍", "文天祥被關押於今日南京市"], "a": 0, "e": "文天祥被擄時是南宋末年，西夏（1227 年）和金（1234 年）早已被蒙古滅亡。元朝皇帝是忽必烈；南宋亡於蒙古；大都是今北京。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-226", "no": 226, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 18 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "因外族入侵而造成國家滅亡的慘劇，在中國歷史上屢見不鮮，其中「女真族」在歷史上曾攻滅哪兩個並立政權？", "o": ["東漢、西晉", "西晉、南宋", "南宋、明朝", "北宋、明朝"], "a": 3, "e": "女真人建立的金滅了北宋；後來女真人建立的清滅了明。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-227", "no": 227, "c": "c12", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 21 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "有關於中國歷史上，中西文化交流的發展，下列敘述何者錯誤？", "o": ["宋元時期指南針廣泛運用於航海上，經阿拉伯人西傳", "絲綢從漢代起就已經傳入了歐洲", "元代以後，西方人開始侵略中國", "蒙古西征有助於東西文化的交流"], "a": 2, "e": "西方人侵略中國是清代鴉片戰爭以後，不是元代以後。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-228", "no": 228, "c": "c3", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 23 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "北宋與外族簽訂了「澶淵之盟」，有關這盟約的意義及內容，下列敘述何者正確？", "o": ["主要是因與外患金兵所簽訂的盟約", "是宋太祖聽從宰相寇準親征後所簽訂", "因北宋大勝，所以外族每年進貢大量的歲幣", "兩朝國家之間藉由此盟約，維持百餘年的和平"], "a": 3, "e": "澶淵之盟讓兩國維持一百多年和平。對象是遼；簽約的是宋真宗；是宋給遼歲幣。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-229", "no": 229, "c": "c8", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 第 25 題（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "關於「宋元時期」中國的商貿情形敘述，下列內容何者錯誤？", "o": ["各地普遍出現「夜市」，同時意味著「坊市分離」制度產生", "泉州、廣州設有市舶司，管理外貿的稅收", "驛站可提供使臣、旅人、官員的歇息", "元代海路、陸路商業都很發達"], "a": 0, "e": "夜市出現代表坊市分離的制度瓦解，而不是產生。", "rep": true, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-230", "no": 230, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 題組 (二) 28（跨課）", "st": "考卷", "ctx": "", "fig": "", "q": "傳說中，蒙古族的祖先是蒼狼與白鹿的結晶，所以成吉思汗被尊為蒼狼的子孫。……他發動第一次西征，先滅消滅花剌子模，打破俄羅斯的聯軍，並將蒙古領土擴大到中亞與南俄，又滅西夏。成吉思汗的子孫窩闊台滅了金國，並派拔都發動第二次西征，逼近威尼斯等地，震驚歐洲人，歐洲人稱之為「黃禍」。……蒙古第三次西征，由旭烈兀出兵，攻下大食的都城。關於蒙古第二次西征最遠到達下列何處？", "o": ["義大利", "印度", "法國", "西班牙"], "a": 0, "e": "蒙古第二次西征逼近威尼斯，最遠到達義大利一帶。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-231", "no": 231, "c": "c5", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 題組 (二) 29（跨課）", "st": "考卷", "ctx": "傳說中，蒙古族的祖先是蒼狼與白鹿的結晶，所以成吉思汗被尊為蒼狼的子孫。……他發動第一次西征，先滅消滅花剌子模，打破俄羅斯的聯軍，並將蒙古領土擴大到中亞與南俄，又滅西夏。成吉思汗的子孫窩闊台滅了金國，並派拔都發動第二次西征，逼近威尼斯等地，震驚歐洲人，歐洲人稱之為「黃禍」。……蒙古第三次西征，由旭烈兀出兵，攻下大食的都城。", "fig": "", "q": "依據上文的說法，三次西征所建立的帝國，涵蓋哪兩大洲？", "o": ["歐洲、美洲", "非洲、美洲", "亞洲、歐洲", "亞洲、非洲"], "a": 2, "e": "三次西征建立的帝國橫跨亞洲和歐洲。", "rep": false, "img": "", "fh": "", "maps": ["map-mongol"], "chk": ""}, {"id": "h3-232", "no": 232, "c": "c4", "src": "考卷 114上金安翰版社會2上A卷 第6次練習 題組 (二) 30（跨課）", "st": "考卷", "ctx": "傳說中，蒙古族的祖先是蒼狼與白鹿的結晶，所以成吉思汗被尊為蒼狼的子孫。……他發動第一次西征，先滅消滅花剌子模，打破俄羅斯的聯軍，並將蒙古領土擴大到中亞與南俄，又滅西夏。成吉思汗的子孫窩闊台滅了金國，並派拔都發動第二次西征，逼近威尼斯等地，震驚歐洲人，歐洲人稱之為「黃禍」。……蒙古第三次西征，由旭烈兀出兵，攻下大食的都城。", "fig": "", "q": "蒙古南下滅宋，當時宋朝的國都為何地？", "o": ["汴京", "大都", "臨安", "長安"], "a": 2, "e": "蒙古南下滅宋時，南宋的國都是臨安。", "rep": false, "img": "", "fh": "", "maps": ["map-ssong"], "chk": ""}, {"id": "h3-m1", "no": null, "c": "c4", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "宋徽宗、宋欽宗被俘北去，宋高宗在南方即位。這件事發生後，宋朝的首都遷到哪裡？", "o": ["汴京", "臨安", "大都", "長安"], "a": 1, "e": "靖康之禍後宋室南渡，南宋定都臨安（今杭州）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m2", "no": null, "c": "c4", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "北宋末年採取「聯金滅遼」的策略，結果造成什麼影響？", "o": ["宋朝收回全部燕雲十六州，從此長保和平", "金國看出宋軍軟弱，南下攻陷汴京", "宋遼簽訂澶淵之盟", "蒙古趁機統一中國"], "a": 1, "e": "金滅遼後看出北宋軍力空虛，1127 年攻陷汴京，北宋滅亡（靖康之禍）。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m3", "no": null, "c": "c8", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "和唐代長安的商人相比，宋代汴京的商人多了哪一項便利？", "o": ["可以在晚上、在住家附近開店營業", "可以在驛站換馬", "可以用貝殼交易", "可以向市舶司申請出海"], "a": 0, "e": "唐代有坊市分離與夜禁；宋代坊市制度瓦解，商店可隨處開設、日夜營業。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m4", "no": null, "c": "c8", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列哪一個畫面最可能出現在《清明上河圖》中？", "o": ["街道兩旁茶坊、酒樓林立", "商店全部集中在圍牆圍起的「市」裡", "騎兵在驛站換馬", "路邊有人在賣烤番薯"], "a": 0, "e": "畫中商店臨街林立，代表坊市制度瓦解；驛站是元代，番薯明代才傳入。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m5", "no": null, "c": "c6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "元代一位原本住在金國統治下的契丹人，在四等人中屬於哪一等？", "o": ["蒙古人", "色目人", "漢人", "南人"], "a": 2, "e": "原受金統治的漢人，以及契丹人、女真人，在元代都歸為「漢人」。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m6", "no": null, "c": "c6", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "元代人口最多、地位卻最低的是哪一等人？", "o": ["蒙古人", "色目人", "漢人", "南人"], "a": 3, "e": "南人是原南宋統治下的人民，人口最多，受壓迫最深。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m7", "no": null, "c": "c5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "關於鐵木真與忽必烈，下列敘述何者正確？", "o": ["鐵木真建立元朝", "忽必烈被尊為成吉思汗", "鐵木真發動第一次西征，忽必烈滅了南宋", "忽必烈定都汴京"], "a": 2, "e": "鐵木真＝成吉思汗，發動西征；忽必烈建元、定都大都、滅南宋。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m8", "no": null, "c": "c5", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "蒙古先後攻滅了西夏、金和南宋，正確的先後順序是？", "o": ["西夏→金→南宋", "金→西夏→南宋", "南宋→金→西夏", "金→南宋→西夏"], "a": 0, "e": "西夏 1227 年亡、金 1234 年亡、南宋 1279 年亡。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m9", "no": null, "c": "c10", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "小明比較「市舶司」與「驛站」，下列整理何者正確？", "o": ["兩者都是海上交通設施", "市舶司管理海上貿易，驛站是陸上交通歇息站", "市舶司是元代才設立的", "驛站負責收關稅"], "a": 1, "e": "市舶司唐代就有，管理海上貿易與關稅；驛站是元代廣設的陸上交通站。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m10", "no": null, "c": "c10", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "宋元時期被譽為「東方第一大港」的城市是？", "o": ["上海", "泉州", "天津", "香港"], "a": 1, "e": "泉州在宋元時設市舶司，元代被譽為世界數一數二的大港。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m11", "no": null, "c": "c3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "澶淵之盟簽訂後，宋遼關係的特色是？", "o": ["遼向宋稱臣", "雙方以父子相稱", "雙方以兄弟相稱，地位對等", "宋割讓汴京給遼"], "a": 2, "e": "澶淵之盟宋遼約為兄弟，是中原王朝與外族對等外交的開始。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m12", "no": null, "c": "c3", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "力勸宋真宗御駕親征澶州的宰相是誰？", "o": ["岳飛", "寇準", "朱熹", "文天祥"], "a": 1, "e": "宰相寇準力勸宋真宗親征，宋軍士氣大振，後來簽訂澶淵之盟。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m13", "no": null, "c": "c11", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "關於理學，下列敘述何者正確？", "o": ["融合伊斯蘭文化", "集大成者是北宋畢昇", "《四書集注》在元代成為科舉定本", "主要傳到西亞和歐洲"], "a": 2, "e": "理學融合佛學，南宋朱熹集大成，元代起《四書集注》成為科舉定本，傳到朝鮮、日本。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m14", "no": null, "c": "c11", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "《四書集注》中的「四書」不包括下列哪一本？", "o": ["論語", "孟子", "中庸", "詩經"], "a": 3, "e": "四書是《大學》《中庸》《論語》《孟子》。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m15", "no": null, "c": "c12", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "宋代發明的西傳途徑，下列配對何者正確？", "o": ["火藥—阿拉伯人", "指南針—阿拉伯人", "活字印刷—蒙古西征", "造紙術—蒙古西征"], "a": 1, "e": "指南針經阿拉伯人傳入歐洲；火藥經蒙古西征西傳；造紙術是唐代怛羅斯之役傳出。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m16", "no": null, "c": "c12", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "下列哪一項不是宋代的科技成就？", "o": ["畢昇發明膠泥活字", "指南針用於航海", "火藥武器用於作戰", "蔡倫改良造紙術"], "a": 3, "e": "蔡倫改良造紙是東漢的事。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m17", "no": null, "c": "c13", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "元代《回回藥方》的出現，說明哪一種文化對中國的影響？", "o": ["印度佛教文化", "伊斯蘭文化", "歐洲基督教文化", "日本文化"], "a": 1, "e": "《回回藥方》融合阿拉伯醫學，是伊斯蘭文化影響中國的例子。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m18", "no": null, "c": "c7", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "占城稻能在宋代大量推廣，主要是因為它具有什麼特性？", "o": ["需要大量灌溉", "早熟、耐旱，可以種在高地", "只能種在北方", "一年只能收一次、產量少"], "a": 1, "e": "占城稻早熟、耐旱，可種在丘陵高地，讓糧食產量大增。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}, {"id": "h3-m19", "no": null, "c": "c1", "src": "仿題", "st": "仿題", "ctx": "", "fig": "", "q": "燕雲十六州被契丹取得，對宋朝造成什麼影響？", "o": ["宋朝失去北方屏障，國防處於劣勢", "成為宋朝的首都", "是占城稻的原產地", "是蒙古西征的起點"], "a": 0, "e": "燕雲十六州是長城防線所在，失去後宋朝北方無險可守。", "rep": false, "img": "", "fh": "", "maps": [], "chk": ""}], "extras": [{"id": "compare", "title": "易混淆比較", "html": "<h3>1. 宋元周邊主要民族政權對照</h3><div class=\"tbl\"><table><thead><tr><th>政權</th><th>建立民族</th><th>建立者</th><th>滅亡其政權之外族</th><th>關鍵特點與歷史影響</th></tr></thead><tbody><tr><td><b>遼</b></td><td>契丹族</td><td>耶律阿保機</td><td>金國（宋金聯軍攻滅）</td><td>取得燕雲十六州；與北宋簽訂澶淵之盟</td></tr><tr><td><b>西夏</b></td><td>黨項族</td><td>李元昊</td><td>蒙古帝國（成吉思汗西征）</td><td>據守西北要道；向遼、宋稱臣納貢</td></tr><tr><td><b>金</b></td><td>女真族</td><td>完顏阿骨打</td><td>蒙古帝國（蒙宋聯軍攻滅）</td><td>發動靖康之禍滅北宋；與南宋以淮河為界對峙</td></tr><tr><td><b>元</b></td><td>蒙古族</td><td>忽必烈（元世祖）</td><td>明朝（朱元璋起兵北伐）</td><td>發動三次西征；消滅南宋統一全中國；推行四等人制</td></tr></tbody></table></div><h3>2. 北宋 vs. 南宋 政治與軍事對比</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>北宋</th><th>南宋</th></tr></thead><tbody><tr><td><b>開國君主</b></td><td>宋太祖（趙匡胤）</td><td>宋高宗（趙構）</td></tr><tr><td><b>首都地點</b></td><td>汴京（今河南開封）</td><td>臨安（今浙江杭州）</td></tr><tr><td><b>主要外患</b></td><td>遼、西夏、金（北宋末期）</td><td>金（南北對峙）、蒙古（南宋末期）</td></tr><tr><td><b>軍政大臣</b></td><td>寇準（力主親征簽訂澶淵之盟）</td><td>岳飛（抗金北伐）、文天祥（抗元殉國）</td></tr><tr><td><b>學術代表</b></td><td>理學初創（周敦頤、程顥、程頤）</td><td>朱熹集理學大成，編撰《四書集注》</td></tr><tr><td><b>滅亡事件</b></td><td>靖康之禍（1127年，徽欽二帝被俘）</td><td>崖山海戰（1279年，南宋軍民覆沒）</td></tr></tbody></table></div><h3>3. 唐代都市 vs. 宋代都市 商業生活型態</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>唐代都市（以長安為代表）</th><th>宋代都市（以汴京、臨安為代表）</th></tr></thead><tbody><tr><td><b>空間限制</b></td><td>嚴格劃分住宅區（坊）與商業區（市）</td><td><b>坊市制度瓦解</b>，店鋪住宅雜處，臨街隨處開店</td></tr><tr><td><b>時間限制</b></td><td>實施「夜禁」，日落暮鼓閉市</td><td><b>取消夜禁</b>，日夜營業，夜市通宵達旦</td></tr><tr><td><b>代表圖像記錄</b></td><td>里坊棋盤式格局圖</td><td>張擇端《清明上河圖》（描繪繁華汴京街市）</td></tr><tr><td><b>使用貨幣</b></td><td>銅錢、絹帛等金屬與實物貨幣</td><td>銅鐵錢流通，並創制世界最早紙幣（四川「交子」）</td></tr></tbody></table></div><h3>4. 元朝四大階級種族制度</h3><div class=\"tbl\"><table><thead><tr><th>階級名稱</th><th>涵蓋族群構成</th><th>政治經濟地位與職責</th><th>備考易錯辨析</th></tr></thead><tbody><tr><td><b>第一等：蒙古人</b></td><td>蒙古各部落族人</td><td>最高統治階層，壟斷中央及地方軍政最高官位</td><td>享有免稅與司法特權</td></tr><tr><td><b>第二等：色目人</b></td><td>西域以西各族（回回、波斯、阿拉伯等）</td><td>地位僅次蒙古人，長於理財，多掌理財政賦稅</td><td>馬可波羅來華時即歸入此類</td></tr><tr><td><b>第三等：漢人</b></td><td>原金國統治下的漢人，以及契丹人、女真人</td><td>地位與任官受限制，法律地位居次</td><td>契丹人、女真人降元後歸為「漢人」而非色目人</td></tr><tr><td><b>第四等：南人</b></td><td>原南宋統治下的漢人及南方各民族</td><td>社會地位最底層，受嚴格不平等差別對待</td><td>人口數量最多，受壓迫最甚</td></tr></tbody></table></div>"}, {"id": "timeline", "title": "時間軸與流程", "html": "<h3>1. 宋元重大事件編年表</h3><div class=\"tbl\"><table><thead><tr><th>年代（西元）</th><th>事件名稱</th><th>核心重點</th></tr></thead><tbody><tr><td><b>947 年</b></td><td>契丹建國稱大遼</td><td>耶律德光自後晉石敬瑭手中割得<b>燕雲十六州</b>，改國號為大遼。</td></tr><tr><td><b>960 年</b></td><td>趙匡胤建立北宋</td><td>趙匡胤發動陳橋兵變稱帝建立宋朝，定都汴京，實行重文輕武政策。</td></tr><tr><td><b>1005 年</b></td><td>宋遼簽訂澶淵之盟</td><td>宋真宗前線禦敵，雙方簽署盟約維持和平，北宋年付遼國歲幣。</td></tr><tr><td><b>1115 年</b></td><td>女真完顏阿骨打建金</td><td>女真族在東北崛起稱雄，北宋採取「聯金滅遼」戰略。</td></tr><tr><td><b>1127 年</b></td><td>靖康之禍與南宋建立</td><td>金兵攻陷汴京俘二帝，北宋亡；宋高宗南渡定都臨安，南宋偏安建立。</td></tr><tr><td><b>1206 年</b></td><td>鐵木真建立蒙古國</td><td>鐵木真統一草原部落，被尊為「成吉思汗」，展開三次歐亞西征。</td></tr><tr><td><b>1271 年</b></td><td>忽必烈建立大元</td><td>元世祖忽必烈定國號為「大元」，定都大都（今北京），推行種族差別待遇。</td></tr><tr><td><b>1279 年</b></td><td>元滅南宋統一中國</td><td>崖山海戰南宋軍民覆亡，元朝成為中國史上首個統治全境的草原民族政權。</td></tr></tbody></table></div><h3>2. 宋代對外政策之「聯外滅敵」連環流程</h3><pre class=\"flow\">【北宋末期】：北宋 ＋ 金國 聯手 ──(滅)──&gt; 遼國\n                                  │\n                                  ▼ 金國隨即看破虛實背盟南侵\n                            北宋滅亡（靖康之禍）\n                                  │\n【南宋時期】：南宋 ＋ 蒙古 聯手 ──(滅)──&gt; 金國\n                                  │\n                                  ▼ 蒙古緊接著全力揮軍南侵\n                            南宋滅亡（元朝一統）</pre>"}, {"id": "charts", "title": "圖表判讀", "html": "<h3>1. 《北宋周邊民族形勢圖》與《燕雲十六州形勢圖》</h3><figure class=\"cimg\"><img src=\"img/map-nsong.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>北宋與周邊民族形勢圖（含燕雲十六州）</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《北宋與周邊民族形勢圖》／《燕雲十六州位置圖》</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 掌握北宋、遼、西夏的相對方位：北方偏東為遼，西北為西夏，西南為大理，中原與華南為北宋。</p><p class=\"li sub\">2. 燕雲十六州地跨長城內外，地處北宋都城汴京正北方的咽喉要塞。</p><p class=\"li\"><b>常見判讀方式</b>：若考題將國名挖空，上方北方大國為「遼」，西北乾旱高原為「西夏」；若題目問及「宋朝為何缺乏山川險阻可守且需歲幣求和」，對應地圖答案必為北方失去「燕雲十六州」。</p><h3>2. 《南宋與金對峙形勢圖》</h3><figure class=\"cimg\"><img src=\"img/map-ssong.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>南宋與周邊民族形勢圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《南宋與金、西夏對峙形勢圖》</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 金國版圖已跨過黃河推進至淮河以北，定都中都（今北京）或汴京。</p><p class=\"li sub\">2. 南宋領土退縮至淮河與秦嶺以南，定都東南沿海臨安（杭州）。</p><p class=\"li sub\">3. 西北為西夏，蒙古高原正值蒙古各部落醞釀壯大。</p><p class=\"li\"><b>常見判讀方式</b>：地圖上中原黃河流域標註為「金」，南方為「南宋」，兩國分界線沿秦嶺淮河分布，即判定為12世紀南宋對峙政局。</p><h3>3. 《蒙古西征與四大汗國疆域圖》</h3><figure class=\"cimg\"><img src=\"img/map-mongol.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>蒙古西征路線及其疆域圖</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《蒙古帝國西征及四大汗國分立圖》</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 蒙古軍隊三次西征路線橫貫歐亞大陸：第一次直入中亞花剌子模；第二次遠征俄羅斯與東歐多瑙河；第三次攻陷西亞巴格達。</p><p class=\"li sub\">2. 疆域結構：包含欽察汗國（俄羅斯一帶）、伊兒汗國（西亞波斯一帶）、察合台汗國（中亞）與窩闊台汗國，以及東方本土的「元朝」。</p><p class=\"li\"><b>常見判讀方式</b>：地圖橫跨歐亞兩洲，東起太平洋、西達東歐多瑙河，並繪有綿密的海上航線（市舶司）與陸上交通線（驛站符牌網絡），此即蒙古帝國歐亞交通圖。</p><h3>4. 《宋代繁華市井圖與元代貨幣》</h3><figure class=\"cimg\"><img src=\"img/qingming.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>《清明上河圖》（插畫）</figcaption></figure><figure class=\"cimg\"><img src=\"img/chao-zhongtong.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>元代紙幣「中統元寶交鈔」</figcaption></figure><figure class=\"cimg\"><img src=\"img/chao-zhiyuan.jpg\" alt=\"\" onclick=\"zoom(this.src)\"><figcaption>元代紙幣「至元通行寶鈔」（對照）</figcaption></figure><p class=\"li\"><b>圖表名稱</b>：《清明上河圖》局部街景／元代「中統元寶交鈔」</p><p class=\"li\"><b>要看懂什麼</b>：</p><p class=\"li sub\">1. 《清明上河圖》街道兩側商肆林立、店面直接面向大道擺設、招牌幡旗飄揚、茶坊酒肆日夜營業。</p><p class=\"li sub\">2. 紙幣鈔券蓋有官印與「通行寶鈔」文字，由官方鈔券機構發行。</p><p class=\"li\"><b>常見判讀方式</b>：若圖像中商鋪「不設封閉市牆」、「隨街設攤」，即代表宋代「坊市制度徹底瓦解」；若出現紙幣票券，則對應宋代「交子」或元代「寶鈔」。</p>"}, {"id": "tips", "title": "口訣與防錯", "html": "<h3>考試防陷阱重點口訣</h3><div class=\"poem\"><b>「宋重文輕武國防弱，十六州失無險托；</b></div><div class=\"poem\"><b>澶淵之盟成兄弟，銀絹歲幣買安和；</b></div><div class=\"poem\"><b>聯金滅遼引靖康，聯蒙滅金宋又亡；</b></div><div class=\"poem\"><b>坊市打破夜市旺，早熟占城人口昌；</b></div><div class=\"poem\"><b>指南火藥字能動，四大階級南最傷。」</b></div><p class=\"li\"><b>防錯關鍵 1（戰略誤判重蹈覆轍）</b>：北宋「聯金滅遼」，引來金兵南侵滅北宋（靖康之禍）；南宋再度「聯蒙滅金」，隨後遭蒙古南下覆滅。兩次政權皆亡於「聯合新興強敵滅舊患」的致命外交互動。</p><p class=\"li\"><b>防錯關鍵 2（元代種族劃分判定）</b>：被金國統治的女真人與契丹人降元後被列入第三等「<b>漢人</b>」，而非色目人；只有原南宋統治下的漢人及南方各民族才算第四等「<b>南人</b>」。</p><p class=\"li\"><b>防錯關鍵 3（三大發明西傳途徑）</b>：火藥於宋代改良投入實戰，由「<b>蒙古西征</b>」傳入西方；指南針應用於航海，由「<b>阿拉伯人</b>」傳播至歐洲；造紙術是唐代怛羅斯之役傳出，切勿與宋代三大發明混淆。</p><p class=\"li\"><b>防錯關鍵 4（外貿港口考點）</b>：宋元海外貿易重鎮以東南沿海的「<b>泉州</b>」與「<b>廣州</b>」為主（設市舶司管理），泉州在元代更被譽為世界第一大港，不可誤選為明清時期的上海或香港。</p>"}]});
